COPY public.digest_tip (id, sequence, group_id, create_uid, write_uid, name, tip_description, create_date, write_date) FROM stdin;
1	800	1	1	1	{"en_US": "Tip: Speed up your workflow with shortcuts", "es_ES": "Consejo: acelere su flujo de trabajo con accesos rápidos"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Speed up your workflow with shortcuts</p>\\n    <p class=\\"tip_content\\">Press ALT in any screen to highlight shortcuts for every button in the screen. It is useful to process multiple documents in batch.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-alt-shortcuts.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: acelere su flujo de trabajo con accesos rápidos</p>\\n    <p class=\\"tip_content\\">Presiona ALT en cualquier pantalla para resaltar accesos rápidos para cada botón en la pantalla. Es útil para procesar múltiples documentos en lote.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-alt-shortcuts.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:18.882056	2026-11-17 08:08:18.882056
2	2100	1	1	1	{"en_US": "Tip: Click on an avatar to chat with a user", "es_ES": "Consejo: Haga clic en un avatar para chatear con el usuario"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Click on an avatar to chat with a user</p>\\n    <p class=\\"tip_content\\">Have a question about a document? Click on the responsible user's picture to start a conversation. If his avatar has a green dot, he is online.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-avatar.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: Haga clic en un avatar para chatear con un usuario</p>\\n    <p class=\\"tip_content\\">¿Tienes una pregunta sobre el documento? Haga clic en la fotografía del usuario responsable para iniciar una conversación. Si el avatar tiene un punto verde, está en línea.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-avatar.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:18.882056	2026-11-17 08:08:18.882056
3	2300	1	1	1	{"en_US": "Tip: A calculator in Odoo", "es_ES": "Consejo: una calculadora en Odoo"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: A calculator in Odoo</p>\\n    <p class=\\"tip_content\\">When editing a number, you can use formulae by typing the `=` character. This is useful when computing a margin or a discount on a quotation, sale order or invoice.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-calculator.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: una calculadora en Odoo</p>\\n    <p class=\\"tip_content\\">Cuando edite un número, puede utilizar fórmulas al escribir el carácter `=`. Esto es útil cuando calcula un margen o un descuento en un presupuesto, pedido de venta o factura.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-calculator.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:18.882056	2026-11-17 08:08:18.882056
4	2400	1	1	1	{"en_US": "Tip: How to ping users in internal notes?", "es_ES": "Consejo: ¿Cómo notificar usuarios en las notas internas?"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: How to ping users in internal notes?</p>\\n    <p class=\\"tip_content\\">Type \\"@\\" to notify someone in a message, or \\"#\\" to link to a channel. Try to notify @OdooBot to test the feature.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-notifications.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: ¿Cómo notificar usuarios en las notas internas?</p>\\n    <p class=\\"tip_content\\">Escriba \\"@\\" para enviar una notificación a alguien por medio de un mensaje, o \\"#\\" para vincular un canal. Intente enviar una notificación a @OdooBot para probar esta función.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-notifications.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:18.882056	2026-11-17 08:08:18.882056
5	2500	1	1	1	{"en_US": "Tip: Knowledge is power", "es_ES": "Consejo: el conocimiento es poder"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Knowledge is power</p>\\n    <p class=\\"tip_content\\">When following documents, use the pencil icon to fine-tune the information you want to receive.\\nFollow a project / sales team to keep track of this project's tasks / this team's opportunities.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-following.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: el conocimiento es poder</p>\\n    <p class=\\"tip_content\\">Cuando siga documentos, use el icono de lápiz para ajustar la información que desea recibir.\\nSiga un proyecto o un equipo de ventas para llevar el seguimiento de las tareas de este proyecto o las oportunidades de este equipo.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/milk-following.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:18.882056	2026-11-17 08:08:18.882056
6	3300	1	1	1	{"en_US": "Tip: Join the Dark Side", "es_ES": "Consejo: únase al lado oscuro"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Join the Dark Side</p>\\n    <p class=\\"tip_content\\">Feeling eye strain? Give your eyes a break by switching to Dark Mode.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/18-web-dark-theme.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: únase al lado oscuro</p>\\n    <p class=\\"tip_content\\">¿Necesita descansar su vista? Use el modo oscuro.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/18-web-dark-theme.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:18.882056	2026-11-17 08:08:18.882056
7	3800	1	1	1	{"en_US": "Tip: Personalize your Home Menu", "es_ES": "Consejo: personalice su menú principal"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Personalize your Home Menu</p>\\n    <p class=\\"tip_content\\">Click and hold on a Menu Item to reorder your Apps to your liking.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/18-web-app-order.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: personalice su menú principal</p>\\n    <p class=\\"tip_content\\">Haga clic y mantenga presionado un elemento del menú para reordenar sus aplicaciones a su gusto.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/digest/static/src/img/18-web-app-order.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:18.882056	2026-11-17 08:08:18.882056
8	700	27	1	1	{"en_US": "Tip: No need to print, put in an envelop and post your invoices", "es_ES": "Consejo: no es necesario que imprima, ponga en un sobre y envíe sus facturas"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: No need to print, put in an envelop and post your invoices</p>\\n    <p class=\\"tip_content\\">Use the “<i>Send by Post</i>” option to post invoices automatically. For the cost of a local stamp, we do all the manual work: your invoice will be printed in the right country, put in an envelop and sent by snail mail. Use this feature from the list view to post hundreds of invoices in bulk.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/invoice-stamps.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: no es necesario que imprima, ponga en un sobre y envíe sus facturas</p>\\n    <p class=\\"tip_content\\">Utilice la opción \\"<i>Enviar por correo electrónico</i>\\" para registrar facturas automáticamente. Por el coste de un sello local, hacemos todo el trabajo manual: su factura se imprimirá en el país correcto, se colocará en un sobre y se enviará por correo postal. Utilice esta función de la vista de lista para registrar cientos de facturas de forma masiva.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/invoice-stamps.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:22.819438	2026-11-17 08:08:22.819438
9	3100	27	1	1	{"en_US": "Tip: Stop chasing the Documents you need", "es_ES": "Consejo: deje de buscar los documentos que necesita"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Stop chasing the Documents you need</p>\\n    <p class=\\"tip_content\\">Missing a document for a banking statement? Use the Documents apps to request it and let the owner upload it at the right place.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/18-invoice-request-document.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: deje de buscar los documentos que necesita</p>\\n    <p class=\\"tip_content\\">¿Falta un documento para un extracto bancario? Use la aplicación Documentos para solicitarlo y permita que el propietario lo suba al lugar correcto.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/account/static/src/img/18-invoice-request-document.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:22.819438	2026-11-17 08:08:22.819438
10	2200	24	1	1	{"en_US": "Tip: Odoo supports configurable products", "es_ES": "Consejo: Odoo admite productos configurables"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Odoo supports configurable products</p>\\n    <p class=\\"tip_content\\">Struggling with a complex product catalog? Try out the Product Configurator to help sales configure a product with different options: colors, size, capacity, etc. Make sale orders encoding easier and error-proof.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/sale_management/static/src/img/milk-Sales-configure-products.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: Odoo admite productos configurables</p>\\n    <p class=\\"tip_content\\">¿Tienes problemas con un catálogo de productos complejo? Prueba el configurador de productos para ayudar a los comerciales a configurar un producto con diferentes opciones: colores, tamaño, capacidad, etc. Facilita la codificación de los pedidos de venta y evita errores.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/sale_management/static/src/img/milk-Sales-configure-products.gif\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:52.487577	2026-11-17 08:08:52.487577
11	2700	24	1	1	{"en_US": "Tip: Sell or buy products in bulk with matrixes", "es_ES": "Consejo: vende o compra productos al por mayor mediante matrices"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Sell or buy products in bulk with matrixes</p>\\n    <p class=\\"tip_content\\">Selling the same product in different sizes or colors? Try the product grid and populate your orders with multiple quantities of each variant. This feature also exists in the Purchase application.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/sale_management/static/src/img/milk-t-shirts.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: vende o compra productos al por mayor mediante matrices</p>\\n    <p class=\\"tip_content\\">¿Vendes el mismo producto en diferentes tamaños o colores? Prueba la cuadrícula de productos y crea pedidos con varias cantidades de cada variante. Esta función también está disponible en la aplicación Compras.</p>\\n    <img src=\\"https://download.odoocdn.com/digests/sale_management/static/src/img/milk-t-shirts.png\\" width=\\"540\\" class=\\"illustration_border\\">\\n</div>\\n            "}	2026-11-17 08:08:52.487577	2026-11-17 08:08:52.487577
12	1000	41	1	1	{"en_US": "Tip: Speed up inventory operations with barcodes", "es_ES": "Consejo: acelere las operaciones de inventario con códigos de barras"}	{"en_US": "<div>\\n    <p class=\\"tip_title\\">Tip: Speed up inventory operations with barcodes</p>\\n    <table class=\\"tip_twocol\\">\\n        <tr>\\n            <td class=\\"tip_twocol_left\\" style=\\"width: 45%;\\">\\n                <img src=\\"https://download.odoocdn.com/digests/stock/static/src/img/barcode.gif\\" class=\\"tip_twocol_img\\" width=\\"240\\">\\n            </td>\\n            <td style=\\"width: 55%;\\">\\n                <p class=\\"tip_content\\" style=\\"margin: 0;\\">Enjoy a quick-paced experience with the Odoo barcode app. It is blazing fast and works even without a stable internet connection. It supports all flows: inventory adjustments, batch picking, moving lots or pallets, low inventory checks, etc. Go to the \\"Apps\\" menu to activate the barcode interface.</p>\\n            </td>\\n        </tr>\\n    </table>\\n    <div style=\\"clear: both;\\"></div>\\n</div>\\n            ", "es_ES": "<div>\\n    <p class=\\"tip_title\\">Consejo: acelere las operaciones de inventario con códigos de barras</p>\\n    <table class=\\"tip_twocol\\">\\n        <tr>\\n            <td class=\\"tip_twocol_left\\" style=\\"width: 45%;\\">\\n                <img src=\\"https://download.odoocdn.com/digests/stock/static/src/img/barcode.gif\\" class=\\"tip_twocol_img\\" width=\\"240\\">\\n            </td>\\n            <td style=\\"width: 55%;\\">\\n                <p class=\\"tip_content\\" style=\\"margin: 0;\\">Disfrute de una experiencia de ritmo rápido con la aplicación de código de barras Odoo. Es increíblemente rápido y funciona incluso sin una conexión a Internet estable. Admite todos los flujos: ajustes de inventario, preparación de pedidos por lotes, mover lotes o paletas, controles de inventario bajo, etc. Vaya al menú \\"Aplicaciones\\" para activar la interfaz de código de barras.</p>\\n            </td>\\n        </tr>\\n    </table>\\n    <div style=\\"clear: both;\\"></div>\\n</div>\\n            "}	2026-11-17 08:10:57.888388	2026-11-17 08:10:57.888388
