help=\\"Calcule los costes de envío y envíe con USPS\\">\\n                                <div class=\\"o_form_label\\">Conector de USPS</div>\\n                                <a href=\\"https://www.odoo.com/documentation/latest/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\" title=\\"Documentación\\" class=\\"o_doc_link\\" target=\\"_blank\\"/>\\n                                <div class=\\"text-muted\\">\\n                                    Calcule los gastos de envío y envíe con USPS<br/>\\n                                    <strong>(vaya a Inicio&gt;Aplicaciones para instalar el módulo)</strong>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_bpost\\" help=\\"Calcule los costes de envío y envíe con bpost\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_bpost\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n\\n                            <setting id=\\"compute_shipping_costs_easypost\\" help=\\"Calcule los costes de envío y envíe con Easypost\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_easypost\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_sendcloud\\" help=\\"Calcule los costes de envío y envíe con Sendcloud\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_sendcloud\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_shiprocket\\" help=\\"Calcule los gastos de envío y envíe con Shiprocket\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_shiprocket\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_starshipit\\" help=\\"Calcule los gastos de envío y envíe con Starshipit\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_starshipit\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                            <setting id=\\"compute_shipping_costs_envia\\" help=\\"Calcule los costes de envío y envíe con Envia.com\\" documentation=\\"/applications/inventory_and_mrp/inventory/shipping/setup/third_party_shipper.html\\">\\n                                <field name=\\"module_delivery_envia\\" widget=\\"upgrade_boolean\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Productos\\" name=\\"product_setting_container\\">\\n                            <setting id=\\"product_attributes\\" help=\\"Establezca los atributos del producto (por ejemplo, color, tamaño) para administrar las variantes\\" documentation=\\"/applications/sales/sales/products_prices/products/variants.html\\">\\n                                <field name=\\"group_product_variant\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_product_variant\\">\\n                                        <button name=\\"183\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Atributos\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"sell_purchase_uom\\" help=\\"Venda y compre productos en diferentes unidades de medida o embalajes\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/products/uom.html\\">\\n                                <field name=\\"group_uom\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_uom\\">\\n                                        <button name=\\"90\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Unidades y embalajes\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Trazabilidad\\" id=\\"production_lot_info\\">\\n                            <setting id=\\"full_traceability\\" help=\\"Obtenga una trazabilidad completa de proveedores a clientes\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/lots_serial_numbers/differences.html\\">\\n                                <field name=\\"group_stock_production_lot\\"/>\\n                                <div class=\\"row mt-2\\" invisible=\\"not group_stock_production_lot\\">\\n                                    <field name=\\"group_stock_lot_print_gs1\\" class=\\"col flex-grow-0 ml16 mr0 pe-2\\"/>\\n                                    <div class=\\"col ps-0\\">\\n                                        <label for=\\"group_stock_lot_print_gs1\\"/>\\n                                        <div class=\\"text-muted\\">Utilice la matriz de datos de nomenclatura GS1 siempre que se impriman los códigos de barras de números de lote y de serie.</div>\\n                                    </div>\\n                                </div>\\n                                <div class=\\"row mt-2\\" invisible=\\"not group_stock_production_lot or not group_stock_tracking_lot\\">\\n                                    <span class=\\"o_form_label\\">Contenido del paquete escaneable</span>\\n                                    <div class=\\"col-12\\">\\n                                        <div class=\\"text-muted\\">Al definir un separador se generará un código QR que contenga todos los números de serie incluidos en el paquete y utilizará el carácter definido para separar los números.</div>\\n                                    </div>\\n                                    <div class=\\"col\\">\\n                                        <label for=\\"barcode_separator\\"/>\\n                                        <field name=\\"barcode_separator\\" class=\\"col flex-grow-0 ml16 mr0 pe-2\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"expiration_dates_serial_numbers\\" help=\\"Establezca fechas de caducidad en los lotes y números de serie\\" invisible=\\"not group_stock_production_lot\\" title=\\"Haga un seguimiento de las fechas de seguimiento de los lotes y números de serie: mejor antes, eliminación, fin de vida, alerta. Dichas fechas se establecen automáticamente en la creación del lote/número de serie en función de los valores establecidos en el producto (en días).\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/lots_serial_numbers/expiration_dates.html\\">\\n                                <field name=\\"module_product_expiry\\"/>\\n                            </setting>\\n                            <setting help=\\"Los números de lote y serie aparecerán en el albarán de entrega\\" invisible=\\"not group_stock_production_lot\\" id=\\"group_lot_on_delivery_slip\\">\\n                                <field name=\\"group_lot_on_delivery_slip\\"/>\\n                            </setting>\\n                            <setting id=\\"owner_stored_products\\" help=\\"Establezca el propietario en productos almacenados\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/misc/owned_stock.html\\">\\n                                <field name=\\"group_stock_tracking_owner\\"/>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Almacén\\" name=\\"warehouse_setting_container\\">\\n                            <setting id=\\"track_product_location\\" help=\\"Monitoree la ubicación del producto en su almacén\\" documentation=\\"/applications/inventory_and_mrp/inventory/warehouses_storage/inventory_management/use_locations.html\\" title=\\"Almacene productos en ubicaciones específicas de su almacén (por ejemplo, contenedores, bastidores) y haga un seguimiento del inventario en consecuencia.\\">\\n                                <field name=\\"group_stock_multi_locations\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_stock_multi_locations\\">\\n                                        <button name=\\"449\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Ubicaciones\\" class=\\"btn-link\\"/><br/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                            <setting id=\\"use_own_routes\\" help=\\"Use sus propias rutas\\" documentation=\\"/applications/inventory_and_mrp/inventory/routes/concepts/use_routes.html\\" title=\\"Añada y personalice las operaciones de ruta para procesar movimientos de productos en su(s) almacén(es): por ejemplo, descargar &gt; control de calidad &gt; stock para productos entrantes, elegir &gt; empaquetar &gt; enviar para productos salientes. También puede establecer estrategias de almacenamiento en ubicaciones de almacenamiento para enviar productos entrantes a ubicaciones hijas específicas de inmediato (por ejemplo, contenedores específicos, bastidores).\\">\\n                                <field name=\\"group_stock_adv_location\\"/>\\n                                <div class=\\"content-group\\">\\n                                    <div class=\\"mt8\\" invisible=\\"not group_stock_adv_location\\">\\n                                        <button name=\\"409\\" icon=\\"oi-arrow-right\\" type=\\"action\\" string=\\"Establecer rutas de almacén\\" class=\\"btn-link\\"/>\\n                                    </div>\\n                                </div>\\n                            </setting>\\n                        </block>\\n                        <block title=\\"Planificación avanzada\\" id=\\"schedule_info\\">\\n                            <setting company_dependent=\\"1\\" help=\\"Configura el horizonte para activar las reglas de reabastecimiento con antelación y adelantarse a la reposición evitando retrasos, o actívalo justo a tiempo ('0 días') para evitar el exceso de stock.\\">\\n                                <field name=\\"horizon_days\\" class=\\"oe_inline\\"/><span> días</span>\\n                            </setting>\\n                            <div id=\\"sale_security_lead\\"/>\\n                            <div id=\\"purchase_po_lead\\"/>\\n                        </block>\\n                        <block title=\\"Logística\\" name=\\"request_vendor_setting_container\\">\\n                            <setting title=\\"Esto añade una ruta de dropshipping aplicable a productos con el fin de solicitar a sus proveedores que entreguen directamente a sus clientes. Un producto para dropship generará una solicitud de presupuesto de compra una vez que se confirme el pedido de venta. Este es un flujo bajo demanda. La dirección de entrega solicitada será la dirección de entrega del cliente y no su almacén.\\" help=\\"Solicite a sus proveedores que entreguen a sus clientes\\" documentation=\\"/applications/inventory_and_mrp/inventory/management/delivery/dropshipping.html\\">\\n                                <field name=\\"module_stock_dropshipping\\"/>\\n                            </setting>\\n                            <setting title=\\"Esto añade una ruta de reposición bajo pedido (fabricación sobre pedido) que se aplica a los productos para generar reposiciones bajo demanda vinculadas a sus pedidos de venta (por ejemplo) tan pronto como se confirman, con un enlace directo. Los pedidos de compra, las órdenes de fabricación, etc. se activan en función de la forma de reposición establecida en el producto (ruta de compra o fabricación).\\" help=\\"Permita la fabricación sobre pedido o automatice los pedidos de compra cuando se venda un producto y obtenga enlaces directos entre documentos.\\" documentation=\\"/applications/inventory_and_mrp/inventory/warehouses_storage/replenishment/mto.html\\">\\n                                <field name=\\"replenish_on_order\\"/>\\n                            </setting>\\n                        </block>\\n                    </app>\\n                </xpath>"}	<?xml version="1.0"?>\n<xpath expr="//form" position="inside">\n                    <app data-string="Inventory" string="Inventory" name="stock" groups="stock.group_stock_manager">\n                        <block title="Operations" name="operations_setting_container">\n                            <setting id="product_packs_tracking" documentation="/applications/inventory_and_mrp/inventory/product_management/product_tracking/package.html" title="Put your products in packs (e.g. parcels, boxes) and track them" help="Put your products in packs (e.g. parcels, boxes) and track them">\n                                <field name="group_stock_tracking_lot"/>\n                            </setting>\n                            <setting id="process_transfers" help="Optimize your transfers by grouping operations together and assigning jobs to workers" documentation="/applications/inventory_and_mrp/inventory/management/misc/batch_transfers.html">\n       