roup_uom\\" invisible=\\"type == 'combo'\\">\\n                                            por\\n                                            <field name=\\"uom_id\\" widget=\\"many2one_uom\\" class=\\"oe_inline\\" style=\\"max-width:136px\\" options=\\"{'no_quick_create': True}\\"/>\\n                                        </span>\\n                                    </div>\\n                                    <label for=\\"standard_price\\" invisible=\\"type == 'combo'                                                     or (not is_product_variant and (                                                         product_variant_count &gt; 1                                                         or (product_variant_count == 0 and is_dynamically_created)                                                     ))\\" id=\\"standard_price_label\\"/>\\n                                    <div name=\\"standard_price_uom\\" invisible=\\"type == 'combo'                                                     or (not is_product_variant and (                                                         product_variant_count &gt; 1                                                         or (product_variant_count == 0 and is_dynamically_created)                                                     ))\\">\\n                                        <field name=\\"standard_price\\" class=\\"oe_inline\\" widget=\\"monetary\\" options=\\"{                                                 'currency_field': 'cost_currency_id',                                                 'field_digits': True,                                             }\\"/>\\n                                        <span groups=\\"uom.group_uom\\">\\n                                            por\\n                                            <field name=\\"uom_id\\" widget=\\"many2one_uom\\" class=\\"oe_inline\\" style=\\"max-width:136px\\" options=\\"{'no_quick_create': True}\\"/>\\n                                        </span>\\n                                    </div>\\n                                    <field name=\\"categ_id\\" string=\\"Categoría\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" options=\\"{'no_create': True}\\" placeholder=\\"Visible para todos\\"/>\\n                                    <field name=\\"currency_id\\" invisible=\\"1\\"/>\\n                                    <field name=\\"cost_currency_id\\" invisible=\\"1\\"/>\\n                                    <field name=\\"product_variant_id\\" invisible=\\"1\\"/>\\n                                </group>\\n                            </group>\\n                            <group name=\\"internal_notes\\" string=\\"Notas internas\\">\\n                                <field colspan=\\"2\\" name=\\"description\\" nolabel=\\"1\\" placeholder=\\"Esta nota es solo para fines internos.\\"/>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Ventas\\" name=\\"sales\\" invisible=\\"1 or not sale_ok\\">\\n                            <group name=\\"sale\\">\\n                                <group string=\\"Ventas adicionales y ventas cruzadas\\" name=\\"upsell\\" invisible=\\"1\\">\\n                                    <field name=\\"uom_ids\\" widget=\\"many2many_uom_tags\\" options=\\"{'no_quick_create': True, 'edit_tags': True}\\" groups=\\"uom.group_uom\\" force_save=\\"1\\" context=\\"{'product_id': product_variant_id if product_variant_count == 1 else False, 'product_ids': product_variant_ids, 'show_variant_name': product_variant_count &gt; 1}\\"/>\\n                                </group>\\n                                <group name=\\"extra_info\\" string=\\"Información adicional\\">\\n                                    <field name=\\"product_tag_ids\\" widget=\\"many2many_tags\\" context=\\"{'product_template_id': id}\\"/>\\n                                </group>\\n                            </group>\\n                            <group>\\n                                <group string=\\"Descripción del presupuesto\\" name=\\"description\\">\\n                                    <field colspan=\\"2\\" name=\\"description_sale\\" nolabel=\\"1\\" placeholder=\\"Esta nota se añade a los pedidos de venta y facturas.\\"/>\\n                                </group>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Precios\\" name=\\"sales_price\\" groups=\\"product.group_product_pricelist\\" invisible=\\"not sale_ok\\">\\n                            <field name=\\"pricelist_rule_ids\\" context=\\"{                                     'form_view_ref': 'product.product_pricelist_item_product_template_form_view',                                 }\\">\\n                                <list>\\n                                    <control>\\n                                        <create name=\\"add_product_price\\" string=\\"Añadir un precio\\"/>\\n                                    </control>\\n                                    <field name=\\"pricelist_id\\" required=\\"is_pricelist_required\\"/>\\n                                    <field name=\\"name\\" string=\\"Aplicado en\\" column_invisible=\\"parent.product_variant_count &lt; 2\\"/>\\n                                    <field name=\\"price\\"/>\\n                                    <field name=\\"min_quantity\\"/>\\n                                    <field name=\\"date_start\\" optional=\\"hide\\"/>\\n                                    <field name=\\"date_end\\" optional=\\"hide\\"/>\\n                                    <field name=\\"company_id\\" groups=\\"base.group_multi_company\\" optional=\\"hide\\"/>\\n\\n                                    <!-- Needed for rule edition & creation on product.product form -->\\n                                    <field name=\\"product_tmpl_id\\" column_invisible=\\"True\\"/>\\n                                </list>\\n                            </field>\\n                        </page>\\n                        <page string=\\"Compra\\" name=\\"purchase\\" invisible=\\"1 or not purchase_ok or type == 'combo'\\" groups=\\"uom.group_uom\\">\\n                            <group name=\\"purchase\\">\\n                                <group string=\\"Facturas de proveedores\\" name=\\"bill\\">\\n                                </group>\\n                            </group>\\n                        </page>\\n                        <page string=\\"Inventario\\" name=\\"inventory\\" groups=\\"uom.group_uom\\" invisible=\\"type in ['service', 'combo']\\">\\n                            <group name=\\"inventory\\">\\n                                <group name=\\"group_lots_and_weight\\" string=\\"Logística\\" invisible=\\"type != 'consu'\\">\\n                                    <label for=\\"weight\\" invisible=\\"product_variant_count &gt; 1 and not is_product_variant\\"/>\\n                                    <div class=\\"o_row\\" name=\\"weight\\" invisible=\\"product_variant_count &gt; 1 and not is_product_variant\\">\\n                                        <field name=\\"weight\\" class=\\"oe_inline\\" style=\\"max-width: 7rem;\\"/>\\n                                        <field name=\\"weight_uom_name\\"/>\\n                                    </div>\\n                                    <label for=\\"volume\\" invisible=\\"product_variant_count &gt; 1 and not is_product_variant\\"/>\\n                                    <div class=\\"o_row\\" name=\\"volume\\" invisible=\\"product_variant_count &gt; 1 and not is_product_variant\\">\\n                                        <field name=\\"volume\\" string=\\"Volumen\\" class=\\"oe_inline\\" style=\\"max-width: 7rem;\\"/>\\n                                        <field name=\\"volume_uom_name\\"/>\\n                                    </div>\\n                                </group>\\n                            </group>\\n                        </page>\\n                    </notebook>\\n                </sheet>\\n                <chatter/>\\n            </form>"}	<?xml version="1.0"?>\n<form string="Product">\n                <sheet name="product_form">\n                    <field name="product_variant_count" invisible="1"/>\n                    <field name="is_product_variant" invisible="1"/>\n                    <field name="attribute_line_ids" invisible="1"/>\n                    <field name="company_id" invisible="1"/>\n                    <div class="oe_button_box" name="button_box">\n                        <!-- Dummy tag for organizing buttons, using position='replace' when inheriting -->\n                        <span id="button_website" invisible="1"/>\n                        <button class="oe_stat_button" name="action_open_documents" type="object" icon="fa-file-text-o">\n                            <field string="Documents" name="product_document_count" widget="statinfo"/>\n                        </button>\n                    </div>\n                    <widget name="web_ribbon" title="Archived" bg_color="text-bg-danger" invisible="active"/>\n                    <field name="id" invisible="True"/>\n                    <field name="image_1920" widget="image" class="oe_avatar" options="{'convert_to_webp': True, 'preview_image': 'image_128', 'zoom': True}"/>\n                    <div class="oe_title">\n                        <label for="name" string="Product"/>\n                        <h1>\n                            <div class="d-flex">\n                                <field name="is_favorite" widget="boolean_favorite" class="me-2" nolabel="1"/>\n                                <field class="text-break" name="name" options="{'line_breaks': False}" widget="text" placeholder="e.g. Cheese Burger"/>\n                            </div>\n                        </h1>\n                    </div>\n                    <div name="options">\n                        <span name="sale_option" class="d-inline-flex">\n                            <field name="sale_ok"/>\n                            <label for="sale_ok"/>\n                        </span>\n                    </div>\n                    <notebook>\n                        <page string="General Information" name="general_information">\n                            <group>\n                                <group name="group_general">\n                                    <field name="active" invisible="1"/>\n                                    <field name="type" widget="radio" options="{'horizontal': True}"/>\n                                    <field name="combo_ids" widget="many2many_tags" placeholder="e.g. Starter - Meal - Desert" invisible="type != 'combo'" options="{                                             'no_quick_create': True,                                             'edit_tags': True,                                         }"/>\n                                    <field name="service_tracking" invisible="1 or type != 'service'"/>\n                                    <field name="product_tooltip" class="fst-italic text-muted" string="" invisible="not product_tooltip"/>\n                                </group>\n                                <group name="group_standard_price">\n                                    <label for="list_price"/>\n                                    <div name="list_price_uom">\n                                        <field name="list_price" class="oe_inline" widget="monetary" options="{'currency_field': 'currency_id', 'field_digits': True}"/>\n                                        <span name="uom_span" groups="uom.group_uom" invisible="type == 'combo'">\n                                            per\n                                            <field name="uom_id" widget="many2one_uom" class="oe_inline" style="max-width:136px" options="{'no_quick_create': True}"/>\n                                        </span>\n                                    </div>\n                                    <label for="standard_price" invisible="type == 'combo'                                                     or (not is_product_variant and (                                                         product_variant_count &gt; 1                                                         or (product_variant_count == 0 and is_dynamically_created)                                                     ))" id="standard_price_label"/>\n                                    <div name="standard_price_uom" invisible="type == 'combo'                                                     or (not is_product_variant and (                                                         product_variant_count &gt; 1                                                         or (product_variant_count == 0 and is_dynamically_created)                                                     ))">\n                                        <field name="standard_price" class="oe_inline" widget="monetary" options="{                                                 'currency_field': 'cost_currency_id',                                                 'field_digits': True,                                             }"/>\n                                        <span groups="uom.group_uom">\n                                            per\n                                            <field name="uom_id" widget="many2one_uom" class="oe_inline" style="max-width:136px" options="{'no_quick_create': True}"/>\n                                        </span>\n                                    </div>\n                                    <field name="categ_id" string="Category"/>\n                                    <field name="company_id" groups="base.group_multi_company" options="{'no_create': True}" placeholder="Visible to all"/>\n                                    <field name="currency_id" invisible="1"/>\n            