>\\n            </select>\\n        </div>\\n        <input type=\\"hidden\\" name=\\"csrf_token\\" t-att-value=\\"request.csrf_token()\\"/>\\n        <input type=\\"hidden\\" name=\\"address_type\\" t-att-value=\\"address_type\\"/>\\n        <input type=\\"hidden\\" name=\\"use_delivery_as_billing\\" t-att-value=\\"use_delivery_as_billing\\"/>\\n        <input type=\\"hidden\\" name=\\"parent_id\\" t-att-value=\\"parent_id\\"/>\\n        <t t-if=\\"partner_id\\">\\n            <input type=\\"hidden\\" name=\\"partner_id\\" t-att-value=\\"partner_id\\"/>\\n        </t>\\n        <t t-if=\\"callback\\">\\n            <input type=\\"hidden\\" name=\\"callback\\" t-att-value=\\"callback\\"/>\\n        </t>\\n        <input type=\\"hidden\\" name=\\"required_fields\\" t-att-value=\\"'name,email'\\"/>\\n    </t>"}	<?xml version="1.0"?>\n<t name="Address Details" t-name="portal.address_form_fields">\n        <div id="div_name" class="col-lg-12 mb-2">\n            <label class="col-form-label" for="o_name">Your name</label>\n            <input id="o_name" type="text" name="name" t-att-value="partner_sudo.name" class="form-control"/>\n        </div>\n        <div class="w-100"/>\n        <div id="div_email" class="col-lg-6 mb-2">\n            <label class="col-form-label" for="o_email">Email</label>\n            <input id="o_email" type="email" name="email" t-att-value="partner_sudo.email" class="form-control"/>\n        </div>\n        <div id="div_phone" class="col-lg-6 mb-2">\n            <label class="col-form-label" for="o_phone">Phone</label>\n            <input id="o_phone" type="tel" name="phone" t-att-value="partner_sudo.phone" class="form-control"/>\n        </div>\n        <t name="b2b_fields">\n            <div class="w-100"/>\n            <t t-if="is_used_as_billing">\n                <t t-set="vat_warning" t-value="current_partner.vat and not current_partner.can_edit_vat()"/>\n                <div id="company_name_div" class="col-lg-6 mb-2">\n                    <label class="col-form-label fw-normal label-optional" for="o_company_name">\n                        Company Name\n                    </label>\n                    <input id="o_company_name" type="text" name="company_name" t-att-value="current_partner.commercial_company_name" t-att-readonly="'1' if not is_main_address else None" class="form-control"/>\n                </div>\n                <div id="div_vat" class="col-lg-6 mb-2">\n                    <label class="col-form-label fw-normal label-optional" for="o_vat">\n                        <t t-out="vat_label"/>\n                    </label>\n                    <input type="text" id="o_vat" name="vat" t-att-value="current_partner.vat" t-att-readonly="'1' if (not is_commercial_address or vat_warning) else None" class="form-control"/>\n                    <!-- Even on new addresses, first tell the customer if their VAT cannot be changed,\n                        then tell them to update it elsewhere if it can be. -->\n                    <div t-if="not is_commercial_address and commercial_partner.is_company and is_main_address" class="col-12 d-none d-lg-block mb-1">\n                        <small class="form-text text-muted">\n                            The VAT number can only be updated on the company account.\n                        </small>\n                    </div>\n                    <div t-elif="vat_warning and is_main_address" class="col-12 d-none d-lg-block mb-1">\n                        <small class="form-text text-muted">\n                            Changing VAT number is not allowed once document(s) have\n                            been issued for your account. Please contact us directly for this\n                            operation.\n                        </small>\n                    </div>\n                </div>\n                <div t-if="not (is_commercial_address or is_main_address)" class="col-12 d-none d-lg-block mb-1">\n                    <small class="form-text text-muted">\n                        The company name and VAT number can only be updated on your main account.\n                        <t t-if="commercial_address_update_url">\n                            If you want to modify it, update\n                            <a t-att-href="commercial_address_update_url">your account details</a>.\n                        </t>\n                    </small>\n                </div>\n            </t>\n        </t>\n        <div id="div_street" class="col-lg-12 mb-2">\n            <label class="col-form-label" for="o_street">\n                Street and Number\n            </label>\n            <input name="street" id="o_street" type="text" class="form-control" t-att-value="partner_sudo.street"/>\n        </div>\n        <div id="div_street2" class="col-lg-12 mb-2">\n            <label class="col-form-label label-optional" for="o_street2">\n                Apartment, suite, etc.\n            </label>\n            <input id="o_street2" type="text" name="street2" class="form-control" t-att-value="partner_sudo.street2"/>\n        </div>\n        <div class="w-100"/>\n        <t t-if="zip_before_city">\n            <div id="div_zip" class="col-md-4 mb-2">\n                <label class="col-form-label" for="o_zip">\n                    Zip Code\n                </label>\n                <input id="o_zip" type="text" name="zip" class="form-control" t-att-value="partner_sudo.zip"/>\n            </div>\n        </t>\n        <div id="div_city" class="col-md-8 mb-2">\n            <label class="col-form-label" for="o_city">City</label>\n            <input id="o_city" type="text" name="city" class="form-control" t-att-value="partner_sudo.city"/>\n        </div>\n        <t t-if="not zip_before_city">\n            <div id="div_zip" class="col-md-4 mb-2">\n                <label class="col-form-label" for="o_zip">\n                    Zip Code\n                </label>\n                <input id="o_zip" type="text" name="zip" class="form-control" t-att-value="partner_sudo.zip"/>\n            </div>\n        </t>\n        <div class="w-100"/>\n        <div id="div_country" class="col-lg-6 mb-2">\n            <label class="col-form-label" for="o_country_id">\n                Country\n            </label>\n            <select id="o_country_id" name="country_id" t-att-class="'pe-none opacity-50 form-select' if not can_edit_country else 'form-select'">\n                <option value="">Country...</option>\n                <option t-foreach="countries" t-as="c" t-att-value="c.id" t-att-selected="c.id == (country.id if country else partner_sudo.country_id.id)" t-att-code="c.code" t-out="c.name"/>\n            </select>\n            <div t-if="not can_edit_country" class="col-12 d-none d-lg-block mb-1">\n                <small class="form-text text-muted">\n                    Changing country is not allowed once document(s) have\n                    been issued for your account. Please contact us directly for this\n                    operation.\n                </small>\n            </div>\n        </div>\n        <div id="div_state" class="col-lg-6 mb-2" t-att-style="not country_states and 'display: none'">\n            <label class="col-form-label label-optional" for="o_state_id">\n                State / Province\n            </label>\n            <select id="o_state_id" name="state_id" class="form-select">\n                <option value="">State / Province...</option>\n                <option t-foreach="country_states" t-as="s" t-att-value="s.id" t-att-selected="s.id == (int(state_id) if state_id else partner_sudo.state_id.id)" t-out="s.name"/>\n            </select>\n        </div>\n        <input type="hidden" name="csrf_token" t-att-value="request.csrf_token()"/>\n        <input type="hidden" name="address_type" t-att-value="address_type"/>\n        <input type="hidden" name="use_delivery_as_billing" t-att-value="use_delivery_as_billing"/>\n        <input type="hidden" name="parent_id" t-att-value="parent_id"/>\