937	16	\N	1	1	peppol.registration.form	peppol.registration	\N	form	account_peppol/wizard/peppol_registration_views.xml	primary	{"en_US": "<form class=\\"form_peppol_registration\\">\\n                <sheet>\\n                    <div class=\\"m-0\\" name=\\"warnings\\" invisible=\\"not peppol_warnings\\">\\n                        <field name=\\"peppol_warnings\\" class=\\"o_field_html\\" widget=\\"actionable_errors\\"/>\\n                    </div>\\n\\n                    <div name=\\"peppol_registration\\">\\n                        <p class=\\"text-muted\\" invisible=\\"not use_parent_connection\\">\\n                            This branch company will use the active Peppol connection found on\\n                            <field name=\\"parent_company_name\\" class=\\"oe_inline o_form_label\\" readonly=\\"1\\"/>\\n                            and send invoices via Peppol on their behalf.\\n                        </p>\\n                        <p class=\\"text-muted\\" invisible=\\"use_parent_connection\\">\\n                            Send electronic invoices, and receive bills automatically via Peppol.\\n                        </p>\\n\\n                        <div class=\\"mb-3\\" invisible=\\"not display_use_parent_connection_selection\\">\\n                            <field name=\\"use_parent_connection_selection\\" widget=\\"radio\\"/>\\n                        </div>\\n\\n                        <group col=\\"1\\">\\n                            <group>\\n                                <field name=\\"peppol_eas\\" placeholder=\\"Peppol ID\\" nolabel=\\"1\\" readonly=\\"use_parent_connection\\" widget=\\"peppol_non_focusable_selection\\" class=\\"o_field_peppol_eas_selection\\"/>\\n                                <field name=\\"peppol_endpoint\\" nolabel=\\"1\\" default_focus=\\"1\\" readonly=\\"use_parent_connection\\"/>\\n                                <field name=\\"contact_email\\" readonly=\\"use_parent_connection\\" string=\\"Email\\"/>\\n                                <field name=\\"phone_number\\" required=\\"edi_mode not in ('demo', 'test')\\" readonly=\\"use_parent_connection\\" string=\\"Phone\\"/>\\n                            </group>\\n                        </group>\\n                        <div class=\\"text-muted col\\" invisible=\\"edi_mode != 'prod'\\">\\n                            By clicking the button below:\\n                            <ul>\\n                                <li>You confirm that you are authorized to register this company on the Peppol network as a legal representative.</li>\\n                                <li>You authorize Odoo to act as your Peppol Service Provider to send and receive e-invoices on your behalf.</li>\\n                                <li>You remain fully responsible for the content, accuracy, and legal compliance of your invoices.</li>\\n                                <li>You accept that any fraudulent activity or spam will result in immediate and permanent exclusion from the Peppol network.</li>\\n                            </ul>\\n                        </div>\\n                        <div class=\\"text-muted col\\" invisible=\\"1\\">\\n                            If you don't have Itsme, please contact\\n                            <a href=\\"https://www.odoo.com/help\\" target=\\"_blank\\">support</a>.\\n                        </div>\\n                        <div class=\\"text-muted col\\" invisible=\\"edi_mode != 'test'\\">\\n                            Test mode allows sending e-invoices through the test Peppol network.<br/>\\n                            By clicking the button below I accept that Odoo may process my e-invoices.\\n                        </div>\\n                    </div>\\n                </sheet>\\n                <footer>\\n\\n                    <button class=\\"btn btn-primary\\" name=\\"button_register_with_itsme\\" type=\\"object\\" invisible=\\"not display_itsme_login\\">\\n                        <b>Authenticate</b>\\n                    </button>\\n\\n                    <!-- No auth buttons -->\\n                    <button string=\\"Activate Peppol\\" name=\\"button_register_peppol_participant\\" type=\\"object\\" class=\\"btn-primary\\" data-hotkey=\\"q\\" invisible=\\"edi_mode != 'prod' or not display_no_auth_buttons\\"/>\\n                    <button string=\\"Activate Peppol (Test)\\" name=\\"button_register_peppol_participant\\" type=\\"object\\" class=\\"btn-primary\\" data-hotkey=\\"q\\" invisible=\\"edi_mode != 'test' or not display_no_auth_buttons\\"/>\\n                    <button string=\\"Activate Peppol (Demo)\\" name=\\"button_register_peppol_participant\\" type=\\"object\\" class=\\"btn-primary\\" data-hotkey=\\"q\\" invisible=\\"edi_mode != 'demo' or not display_no_auth_buttons\\"/>\\n                    <button string=\\"Cancel\\" class=\\"btn-secondary\\" special=\\"cancel\\" data-hotkey=\\"x\\"/>\\n                </footer>\\n            </form>", "es_ES": "<form class=\\"form_peppol_registration\\">\\n                <sheet>\\n                    <div class=\\"m-0\\" name=\\"warnings\\" invisible=\\"not peppol_warnings\\">\\n                        <field name=\\"peppol_warnings\\" class=\\"o_field_html\\" widget=\\"actionable_errors\\"/>\\n                    </div>\\n\\n                    <div name=\\"peppol_registration\\">\\n                        <p class=\\"text-muted\\" invisible=\\"not use_parent_connection\\">\\n                            Esta sucursal utilizará la conexión Peppol activa que se encuentra en\\n                            <field name=\\"parent_company_name\\" class=\\"oe_inline o_form_label\\" readonly=\\"1\\"/>\\n                            y enviar facturas a través de Peppol en tu nombre.\\n                        </p>\\n                        <p class=\\"text-muted\\" invisible=\\"use_parent_connection\\">\\n                            Envía y recibe facturas electrónicas automáticamente mediante Peppol.\\n           