                                <span t-out=\\"discount_amount\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">50.00</span>\\n                                <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                            </span>\\n                            <span t-else=\\"\\">\\n                                <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                                <span t-out=\\"discount_amount\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">50.00</span>\\n                            </span>\\n                        </div>\\n                    </div>\\n                    <br/>\\n                </div>\\n                <div class=\\"oe_structure\\"/>\\n\\n\\n                <div t-if=\\"invoiceTotal\\" id=\\"invoices\\">\\n                    <br/>\\n                    <h6 class=\\"bg-secondary p-1 fw-bold\\">Facturas</h6>\\n                    <table class=\\"table table-sm table-borderless\\">\\n                        <tbody>\\n                        <t t-foreach=\\"invoiceList\\" t-as=\\"invoiceSession\\" class=\\"border-bottom border-secondary\\">\\n                            <t t-if=\\"invoiceSession['invoices']\\">\\n                                <tr t-foreach=\\"invoiceSession[&quot;invoices&quot;]\\" t-as=\\"invoice\\">\\n                                    <td class=\\"ps-2 fw-bold\\"><span t-out=\\"invoice['name']\\">Nombre de la factura</span></td>\\n                                    <td><span t-out=\\"invoice['order_ref']\\">Ref. del pedido</span></td>\\n                                    <td class=\\"text-end\\">\\n                                        <span t-if=\\"currency['position']\\">\\n                                            <span t-out=\\"invoice['total']\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">123.45</span><span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                                        </span>\\n                                        <span t-else=\\"\\">\\n                                            <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span><span t-out=\\"invoice['total']\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">123.45</span>\\n                                        </span>\\n                                    </td>\\n                                </tr>\\n                            </t>\\n                        </t>\\n                        <tr>\\n                            <td><strong>Total</strong></td>\\n                            <td/>\\n                            <td class=\\"text-end\\"><strong>\\n                                <span t-if=\\"currency['position']\\">\\n                                    <span t-out=\\"invoiceTotal\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">123.45</span><span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                                </span>\\n                                <span t-else=\\"\\">\\n                                    <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span><span t-out=\\"invoiceTotal\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">123.45</span>\\n                                </span>\\n                            </strong></td>\\n                        </tr>\\n                        </tbody>\\n                    </table>\\n                </div>\\n                <div class=\\"oe_structure\\"/>\\n                <t id=\\"closing_session\\">\\n                    <h6 class=\\"bg-secondary p-1 fw-bold\\">Control de la sesión</h6>\\n                    <div class=\\"oe_structure\\"/>\\n                    <div style=\\"break-inside: avoid;\\">\\n                        <t t-if=\\"cash_rounding_total\\">\\n                            <strong>Redondeo de efectivo:\\n                                <span t-if=\\"currency['position']\\">\\n                                    <span t-out=\\"cash_rounding_total\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">0.00</span>\\n                                    <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                                </span>\\n                                <span t-else=\\"\\">\\n                                    <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                                    <span t-out=\\"cash_rounding_total\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">0.00</span>\\n                                </span>\\n                            </strong>\\n                            <br/>\\n                        </t>\\n                        <strong>Total:\\n                            <span t-if=\\"currency['position']\\">\\n                                <span t-out=\\"currency[&quot;total_paid&quot;]\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">99.99</span><span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                            </span>\\n                            <span t-else=\\"\\">\\n                                <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span><span t-out=\\"currency[&quot;total_paid&quot;]\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">99.99</span>\\n                            </span>\\n                        </strong>\\n                        <br/>\\n                        <strong>Número de transacciones: <span t-out=\\"nbr_orders\\">10</span></strong>\\n                    </div>\\n                    <br/>\\n                    <div class=\\"oe_structure\\"/>\\n                    <table class=\\"table table-sm table-borderless\\">\\n                        <thead><tr>\\n                            <th class=\\"text-start\\">Nombre</th>\\n                            <th/>\\n                            <th class=\\"text-end\\">Esperado</th>\\n                            <th t-if=\\"(state == 'closed' or state == 'multiple') and payments\\" class=\\"text-end\\">Contado</th>\\n                            <th t-if=\\"(state == 'closed' or state == 'multiple') and payments\\" class=\\"text-end\\">Diferencia</th>\\n                        </tr></thead>\\n                        <tbody>\\n                            <t t-foreach=\\"payments\\" t-as=\\"method\\">\\n                                <t t-if=\\"method['count']\\">\\n                                    <tr>\\n                                        <td><strong><span t-out=\\"method['name']\\">Efectivo</span></strong></td>\\n                                        <td/>\\n                                        <td class=\\"text-end\\">\\n                                            <span t-if=\\"currency['position']\\">\\n                                                <span t-out=\\"method['final_count']\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">100.00</span><span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                                            </span>\\n                                            <span t-else=\\"\\">\\n                                                <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span><span t-out=\\"method['final_count']\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">100.00</span>\\n                                            </span>\\n                                        </td>\\n                                        <td t-if=\\"(state == 'closed' or state == 'multiple') and payments\\" class=\\"text-end\\">\\n                                            <span t-if=\\"currency['position']\\">\\n                                                <span t-out=\\"method['money_counted']\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">95.00</span><span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                                            </span>\\n                                            <span t-else=\\"\\">\\n                                                <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span><span t-out=\\"method['money_counted']\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">95.00</span>\\n                                            </span>\\n                                        </td>\\n                                        <td t-if=\\"(state == 'closed' or state == 'multiple') and payments\\" class=\\"text-end\\">\\n                                            <span t-if=\\"currency['position']\\">\\n                                                <span t-out=\\"method['money_difference']\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">5.00</span><span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                                            </span>\\n                                            <span t-else=\\"\\">\\n                                                <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span><span t-out=\\"method['money_difference']\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">5.00</span>\\n                                            </span>\\n                                        </td>\\n                                    </tr>\\n                                    <tr t-if=\\"(state == 'closed' or state == 'multiple') and payments\\" t-foreach=\\"method['cash_moves']\\" t-as=\\"move\\">\\n                                        <td/>\\n                                        <td><span t-out=\\"move['name']\\">Movimientos de efectivo 1</span></td>\\n                                        <td class=\\"text-end\\">\\n                                            <span t-if=\\"currency['position']\\">\\n                                                <span t-out=\\"move['amount']\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">50.00</span><span t-out=\\"currency[&quot;symbol&quot;]\\">$</span>\\n                                            </span>\\n                                            <span t-else=\\"\\">\\n                                                <span t-out=\\"currency[&quot;symbol&quot;]\\">$</span><span t-out=\\"move['amount']\\" t-options=\\"{'widget': 'float', 'precision': currency['precision']}\\">50.00</span>\\n                                            </span>\\n                                        </td>\\n                                        <td/>\\n                                        <td/>\\n                                    </tr>\\n                                </t>\\n                            </t>\\n                        </tbody>\\n                    </table>\\n                    <div class=\\"oe_structure\\"/>\\n                    <div t-if=\\"opening_note or closing_note\\" style=\\"break-inside: avoid;\\">\\n                        <br/>\\n                        <br/>\\n                        <span t-if=\\"opening_note\\" id=\\"opening_note\\">\\n                            <strong>Nota de apertura de la sesión:</strong>\\n                            <span t-out=\\"opening_note\\" t-options=\\"{'widget': 'text'}\\">Nota de apertura de ejemplo</span>\\n                        </span>\\n                        <br/>\\n                        <span t-if=\\"closing_note\\" id=\\"closing_note\\">\\n                            <strong>Nota de cierre de sesión:</strong>\\n                            <span t-out=\\"closing_note\\" t-options=\\"{'widget': 'text'}\\">Nota de cierre de ejemplo</span>\\n                        </span>\\n                    </div>\\n                </t>\\n                <div id=\\"end_report\\" style=\\"page-break-after: always;\\"/>\\n            </div>\\n        </t>"}	<?xml version="1.0"?>\n<t t-name="point_of_sale.pos_session_sales_details">\n            <div class="page">\n                <div class="bg-secondary p-3" id="header">\n                    <div class="row">\n                        <div class="col-3 d-flex flex-column justify-content-center">\n                            <br/>\n                            <br/>\n                            <div class="text-start" style="font-size:0.85rem;">\n                                <span t-esc="company.name"/>\n                                <address class="mb-0 text-muted" t-field="env.company.partner_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;], &quot;no_marker&quot;: True}"/>\n                                <span t-if="company.vat" class="company-vat">VAT: <t t-esc="company.vat"/></span>\n                            </div>\n                        </div>\n                        <div class="col-6 text-center">\n                            <h2 t-if="state == 'closed' or state == 'opened'" id="daily_report_title">Daily Sales Report\n                                <t t-if="state == 'closed'">Z</t>\n                                <t t-else="">X</t>\n                            </h2>\n                            <t t-if="session_name">\n                                Session ID: <span t-out="session_name">987657</span>\n                            </t>\n                        </div>\n                    </div>\n                </div>\n                <div class="row">\n                    <div class="col-12 text-end mt-2">\n                        <span class="badge bg-light text-dark border border-dark p-2">\n                            <t t-set="date_format" t-value="env['res.lang']._get_data(code=env.user.lang).date_format"/>\n                            <strong>    As of <span t-esc="datetime.datetime.now()" t-options="{'widget': 'datetime'}"/>\n                            </strong>\n                        </span>\n                    </div>\n                </div>\n                <div class="text-center" style="break-inside: avoid;">\n                    <t t-if="state == 'multiple'">\n                        <h2>Sales Details</h2>\n                        <div class="oe_structure"/>\n                        <t t-if="config_names">\n                            <strong>Config names</strong>\n                            <t t-foreach="config_names" t-as="name">\n                                <span t-out="name">Sample Config Name</span>,\n                            </t>\n                        </t>\n                    </t>\n                    <t t-if="date_start and date_stop">\n                        <span t-out="date_start" t-options="{'widget': 'datetime'}">2-03-2000 9:00 AM</span> - <span t-out="date_stop" t-options="{'widget': 'datetime'}">Demo 3-03-2000 5:00 PM</span>\n                    </t>\n                </div>\n                <br/>\n                <br/>\n                <div class="oe_structure"/>\n                <!-- Orderlines -->\n                <div t-if="products" id="sales">\n                    <h6 class="bg-secondary p-1 fw-bold">Sales</h6>\n                    <div class="oe_structure"/>\n                    <table class="table table-sm table-borderless">\n                        <tbody>\n                            <tr t-foreach="products" t-as="category" class="border-bottom border-secondary">\n                                <td class="ps-2 fw-bold"><span t-out="category['name']">Technical Stuffs</span></td>\n                                <td class="fw-bold"/>\n                                <td class="fw-bold"/>\n                                <td class="text-end fw-bold"><span t-out="category['qty']">5</span></td>\n                                <td class="text-end fw-bold">\n                                    <t t-if="currency['position']">\n                                        <span t-out="category['total']" t-options="{'widget': 'float', 'precision': currency['precision']}">10000.00</span><span t-out="currency[&quot;symbol&quot;]">$</span>\n                                    </t>\n                                    <t t-else="">\n                                        <span t-out="currency[&quot;symbol&quot;]">$</span><span t-out="category['total']" t-options="{'widget': 'float', 'precision': currency['precision']}">10000.00</span>\n                                    </t>\n                                </td>\n                                <tr t-foreach="category['products']" t-as="line" class="border-bottom border-secondary">\n                                    <td class="ps-5"><span t-out="line['product_name']">Laptop model x</span><span t-if="line['combo_products_label']" t-out="line['combo_products_label']"/></td>\n                                    <td/>\n                                    <td class="text-end">\n                                        <t t-if="line['barcode']">\n                                            <img t-att-src="'/report/barcode/Code128/'+line['barcode']" style="width:230px; height:23px" alt="Barcode"/>\n                                        </t>\n                                    </td>\n                                    <td class="text-end">\n                                        <span t-out="line['quantity']">5</span>\n                                        <t t-if="line[&quot;uom&quot;] != &quot;Units&quot;">\n                                            <span t-out="line[&quot;uom&quot;]">Unit</span>\n                                        </t>\n                                    </td>\n                                    <td class="text-end">\n                                        <t t-if="currency['position']">\n                                            <span t-out="line[&quot;base_amount&quot;]" t-options="{'widget': 'float', 'precision': currency['precision']}">567789</span><span t-out="currency[&quot;symbol&quot;]">$</span>\n                                        </t>\n                                        <t t-else="">\n                                            <span t-out="currency[&quot;symbol&quot;]">$</span><span t-out="line[&quot;base_amount&quot;]" t-options="{'widget': 'float', 'precision': currency['precision']}">567789</span>\n                                        </t>\n\n                                        <t t-if="line[&quot;discount&quot;] != 0">\n                                            Disc: <span t-out="line[&quot;discount&quot;]">45</span>%\n                                        </t>\n                                    </td>\n                                </tr>\n                            </tr>\n                            <tr>\n                                <td><strong>Total</strong></td>\n                                <td/>\n                                <td/>\n                                <td class="text-end"><strong><span t-out="products_info['qty']">5</span></strong></td>\n                                <td class="text-end">\n                                    <t t-if="currency['position']">\n                                        <strong><span t-out="products_info[&quot;total&quot;]" t-options="{'widget': 'float', 'precision': currency['precision']}">10000</span><span t-out="currency[&quot;symbol&quot;]">$</span></strong>\n                                    </t>\n                                    <t t-else="">\n                                        <strong><span t-out="currency[&quot;symbol&quot;]">$</span><span t-out="products_info[&quot;total&quot;]" t-options="{'widget': 'float', 'precision': currency['precision']}">1000</span></strong>\n                                    </t>\n                                </td>\n                            </tr>\n                        </tbody>\n                    </table>\n                </div>\n                <div class="oe_structure"/>\n                <div t-if="taxes" id="taxe_sales" style="page-break-inside: avoid;">\n                    <h6 class="bg-secondary p-1 fw-bold w-50 ms-auto">Taxes on sales</h6>\n                    <table class="table table-sm table-borderless w-50 ms-auto">\n                        <tbody>\n                        <tr t-foreach="taxes" t-as="tax" class="border-bottom border-secondary">\n                            <td class="ps-2 fw-bold"><span t-out="tax['name']">Demo Name</span></td>\n                            <td class="text-end">\n                                <t t-if="currency['position']">\n                                    <span t-out="tax['tax_amount']" t-options="{'widget': 'float', 'precision': currency['precision']}">0.00</span><span t-out="currency[&quot;symbol&quot;]">$</span>\n                                </t>\n                                <t t-else="">\n                                    <span t-out="currency[&quot;symbol&quot;]">$</span><span t-out="tax['tax_amount']" t-options="{'widget': 'float', 'precision': currency['precision']}">0.00</span>\n                                </t>\n\n                            </td>\n                            <td class="text-end">\n                                <t t-if="currency['position']">\n                                    <span t-out="tax['base_amount']" t-options="{'widget': 'float', 'precision': currency['precision']}">0.00</span><span t-out="currency[&quot;symbol&quot;]">$</span>\n                                </t>\n                                <t t-else="">\n                                    <span t-out="currency[&quot;symbol&quot;]">$</span><span t-out="tax['base_amount']" t-options="{'widget': 'float', 'precision': currency['precision']}">0.00</span>\n                                </t>\n                            </td>\n                        </tr>\n                        <tr>\n                            <td><strong>Total</strong></td>\n                            <td class="text-end">\n                                <t t-if="currency['position']">\n                                    <strong><span t-out="taxes_info[&quot;tax_amount&quot;]" t-options="{'widget': 'float', 'precision': currency['precision']}">0.00</span><span t-out="currency[&quot;symbol&quot;]">$</span></strong>\n                                </t>\n                                <t t-else="">\n                                    <strong><span t-out="currency[&quot;symbol&quot;]">$</span><span t-out="taxes_info[&quot;tax_amount&quot;]" t-options="{'widget': 'float', 'precision': currency['precision']}">0.00</span></strong>\n                                </t>\n                            </td>\n                            <td class="text-end">\n                                <t t-if="currency['position']">\n                                    <strong><span t-out="taxes_info[&quot;base_amount&quot;]" t-options="{'widget': 'float', 'precision': currency['precision']}">0.00</span><span t-out="currency[&quot;symbol&quot;]">$</span></strong>\n                                </t>\n                                <t t-else="">\n                                    <strong><span t-out="currency[&quot;symbol&quot;]">$</span><span t-out="taxes_info[&quot;base_amount&quot;]" t-options="{'widget': 'float', 'precision': currency['precision']}">0.00</span></strong>\n                                </t>\n                            </td>\n                        </tr>\n                        </tbody>\n                    </table>\n                    <div class="oe_structure"/>\n                </div>\n                <div t-if="refund_products" id="refunds">\n                    <h6 class="bg-secondary p-1 fw-bold">Refunds</h6>\n                    <table class="table table-sm table-borderless">\n                        <tbody>\n                            <tr t-foreach="refund_products" t-as="category" class="border-bottom border-secondary">\n                                <td class="ps-2 fw-bold"><span t-out="category['name']">Technical Stuff</span></td>\n                                <td class="fw-bold"/>