nding from <field name=\\"peppol_parent_company_name\\" class=\\"oe_inline o_form_label\\" readonly=\\"1\\"/>.\\n                        </div>\\n\\n                        <div class=\\"d-flex gap-1 action_buttons mt-2\\" invisible=\\"peppol_use_parent_company or account_peppol_proxy_state not in ('sender', 'smp_registration', 'receiver')\\">\\n                            <!-- Deprecated button for advanced configuration -->\\n                            <button string=\\"Advanced Configuration\\" icon=\\"oi-arrow-right\\" name=\\"button_open_peppol_config_wizard\\" type=\\"object\\" class=\\"btn-link\\" invisible=\\"True\\"/>\\n                            <button string=\\"Disconnect Peppol\\" name=\\"button_peppol_deregister\\" type=\\"object\\" class=\\"btn-primary me-1\\"/>\\n                        </div>\\n                        <div class=\\"d-flex gap-1 action_buttons\\" colspan=\\"3\\">\\n                            <!-- Not yet registered on Peppol -->\\n                            <div invisible=\\"peppol_use_parent_company or account_peppol_proxy_state != 'not_registered'\\">\\n                                <div class=\\"text-muted\\">\\n                                    Allow sending and receiving invoices through the Peppol network\\n                                </div>\\n                                <button name=\\"action_open_peppol_form\\" type=\\"object\\" string=\\"Activate Peppol\\" class=\\"oe_highlight mt-2\\"/>\\n                            </div>\\n                            <!-- deprecated Registered on Peppol -->\\n                            <div invisible=\\"True\\" class=\\"mt-3\\">\\n                                <button string=\\"Register with Odoo\\" name=\\"button_peppol_register_sender_as_receiver\\" type=\\"object\\" class=\\"btn-primary me-1\\" invisible=\\"account_peppol_proxy_state != 'sender'\\"/>\\n                            </div>\\n                            <!--Branch company connected to parent's active peppol connection.-->\\n                            <div invisible=\\"not peppol_use_parent_company\\" class=\\"mt-2\\">\\n                                <button string=\\"Disconnect\\" name=\\"button_peppol_disconnect_branch_from_parent\\" type=\\"object\\" class=\\"btn-secondary me-1\\"/>\\n                            </div>\\n                        </div>\\n                    </div>\\n                    <div class=\\"row mb-3\\" invisible=\\"not account_is_token_out_of_sync\\">\\n                        <div class=\\"content-group\\">\\n                            Your Peppol identification is:\\n                            <field name=\\"account_peppol_edi_identification\\" nolabel=\\"1\\"/>\\n                        </div>\\n                        <div class=\\"content-group mt-3 alert alert-danger\\" role=\\"alert\\">\\n                            <div class=\\"d-flex align-items-start\\">\\n                                <i class=\\"fa fa-exclamation-triangle fa-lg me-3 mt-1\\" aria-hidden=\\"true\\"/>\\n                                <div>\\n                                    <span><strong>Disconnected from Peppol!</strong></span>\\n                                    <p>\\n                                        Your database is not linked to Peppol anymore. This might be due to a database duplication or restoration.\\n                                        <br/><a class=\\"text-info\\" href=\\"https://www.odoo.com/help-form\\" target=\\"_blank\\"><strong>Contact us</strong></a>\\n                                        to reconnect your database to Peppol.\\n                                    </p>\\n                                </div>\\n                            </div>\\n\\n                            <!-- hidden for now until a proper fix is in place, buttons were not removed as we will need them later-->\\n                            <div class=\\"mt-3 d-flex gap-1\\" invisible=\\"True\\">\\n                                <button name=\\"but