945	16	\N	1	1	report_saleorder_document	\N	sale.report_saleorder_document	qweb	sale/report/ir_actions_report_templates.xml	primary	{"en_US": "<t t-name=\\"sale.report_saleorder_document\\">\\n    <t t-call=\\"web.external_layout\\">\\n        <t t-set=\\"doc\\" t-value=\\"doc.with_context(lang=doc.partner_id.lang)\\"/>\\n        <t t-set=\\"forced_vat\\" t-value=\\"doc.fiscal_position_id.foreign_vat\\"/> <!-- So that it appears in the footer of the report instead of the company VAT if it's set -->\\n        <t t-set=\\"address\\">\\n            <div t-field=\\"doc.partner_id\\" class=\\"mb-0\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n            <p t-if=\\"doc.partner_id.vat\\" class=\\"mb-0\\">\\n                <t t-if=\\"doc.company_id.account_fiscal_country_id.vat_label\\" t-out=\\"doc.company_id.account_fiscal_country_id.vat_label\\"/>\\n                <t t-else=\\"\\">Tax ID</t>: <span t-field=\\"doc.partner_id.vat\\"/>\\n            </p>\\n        </t>\\n        <t t-if=\\"doc.partner_shipping_id == doc.partner_invoice_id                              and doc.partner_invoice_id != doc.partner_id                              or doc.partner_shipping_id != doc.partner_invoice_id\\">\\n            <t t-set=\\"information_block\\">\\n                <t t-if=\\"doc.partner_shipping_id == doc.partner_invoice_id\\">\\n                    <strong>\\n                        Invoicing and Shipping Address\\n                    </strong>\\n                    <div t-field=\\"doc.partner_invoice_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                </t>\\n                <div t-else=\\"\\" class=\\"row\\">\\n                    <div t-if=\\"doc.partner_id != doc.partner_invoice_id\\" t-att-class=\\"doc.partner_id != doc.partner_shipping_id and 'col-6 pe-1'\\">\\n                        <strong>\\n                            Invoicing Address\\n                        </strong>\\n                        <div t-field=\\"doc.partner_invoice_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                    </div>\\n                    <div t-if=\\"doc.partner_id != doc.partner_shipping_id\\" t-att-class=\\"doc.partner_id != doc.partner_invoice_id and 'col-6 ps-1'\\">\\n                        <strong>\\n                            Shipping Address\\n                        </strong>\\n                        <div t-field=\\"doc.partner_shipping_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                    </div>\\n                </div>\\n            </t>\\n        </t>\\n        <div class=\\"page\\">\\n            <div class=\\"oe_structure\\"/>\\n\\n            <t t-set=\\"is_proforma\\" t-value=\\"env.context.get('proforma', False) or is_pro_forma\\"/>\\n            <t t-set=\\"layout_document_title\\">\\n                <span t-if=\\"is_proforma\\">Pro-Forma Invoice # </span>\\n                <span t-elif=\\"doc.state in ['draft','sent']\\">Quotation # </span>\\n                <span t-else=\\"\\">Order # </span>\\n                <span t-field=\\"doc.name\\">SO0000</span>\\n            </t>\\n\\n            <div class=\\"row mb-4\\" id=\\"informations\\">\\n                <div t-if=\\"doc.client_order_ref\\" class=\\"col\\" name=\\"informations_reference\\">\\n                    <strong>Your Reference</strong>\\n                    <div t-field=\\"doc.client_order_ref\\">SO0000</div>\\n                </div>\\n                <div t-if=\\"doc.date_order\\" class=\\"col\\" name=\\"informations_date\\">\\n                    <strong t-if=\\"is_proforma\\">Issued Date</strong>\\n                    <strong t-elif=\\"doc.state in ['draft', 'sent']\\">Quotation Date</strong>\\n                    <strong t-else=\\"\\">Order Date</strong>\\n                    <div t-field=\\"doc.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2023-12-31</div>\\n                </div>\\n                <div t-if=\\"doc.validity_date and doc.state in ['draft', 'sent']\\" class=\\"col\\" name=\\"expiration_date\\">\\n                    <strong>Expiration</strong>\\n                    <div t-field=\\"doc.validity_date\\">2023-12-31</div>\\n                </div>\\n                <div t-if=\\"doc.commitment_date\\" class=\\"col\\" name=\\"delivery_date\\">\\n                    <strong>Delivery Date</strong>\\n                    <div t-field=\\"doc.commitment_date\\" t-options=\\"{'widget': 'date'}\\">\\n                        2023-12-31\\n                    </div>\\n                </div>\\n                <div t-if=\\"doc.user_id.name\\" class=\\"col\\">\\n                    <strong>Salesperson</strong>\\n                    <div t-field=\\"doc.user_id\\">Mitchell Admin</div>\\n                </div>\\n            </div>\\n\\n            <!-- Is there a discount on at least one line? -->\\n            <t t-set=\\"lines_to_report\\" t-value=\\"doc._get_order_lines_to_report()\\"/>\\n            <t t-set=\\"display_discount\\" t-value=\\"any(l.discount &gt; 0 for l in lines_to_report)\\"/>\\n            <!-- Hide taxes AND show taxed amounts on lines -->\\n            <t t-set=\\"hide_taxes_details\\" t-value=\\"False\\"/>\\n            <t t-set=\\"display_taxes\\" t-value=\\"not hide_taxes_details and any(l._has_taxes() for l in lines_to_report)\\"/>\\n\\n            <div class=\\"oe_structure\\"/>\\n            <table class=\\"o_has_total_table table o_main_table table-borderless\\">\\n                <!-- In case we want to repeat the header, remove \\"display: table-row-group\\" -->\\n                <thead style=\\"display: table-row-group\\">\\n                    <!-- Initialize the dynamic column counter -->\\n                    <t t-set=\\"colspan_count\\" t-value=\\"0\\"/>\\n                    <tr>\\n                        <th name=\\"th_description\\" class=\\"text-start\\">\\n                            <t t-set=\\"colspan_count\\" t-value=\\"colspan_count + 1\\"/>\\n                            Description\\n                        </th>\\n                        <th name=\\"th_quantity\\" class=\\"text-end text-nowrap\\">\\n                            <t t-set=\\"colspan_count\\" t-value=\\"colspan_count + 1\\"/>\\n                            Quantity\\n                        </th>\\n                        <th name=\\"th_priceunit\\" class=\\"text-end text-nowrap\\">\\n                            <t t-set=\\"colspan_count\\" t-value=\\"colspan_count + 1\\"/>\\n                            Unit Price\\n                        </th>\\n                        <th name=\\"th_discount\\" t-if=\\"display_discount\\" class=\\"text-end\\">\\n                            <t t-set=\\"colspan_count\\" t-value=\\"colspan_count + 1\\"/>\\n                            <span>Disc.%</span>\\n                        </th>\\n                        <th name=\\"th_taxes\\" t-if=\\"display_taxes\\" class=\\"text-end\\">\\n                            <t t-set=\\"colspan_count\\" t-value=\\"colspan_count + 1\\"/>\\n                            <span>Taxes</span>\\n                        </th>\\n                        <th name=\\"th_subtotal\\" class=\\"text-end\\">\\n                            <span>Amount</span>\\n                        </th>\\n                    </tr>\\n                </thead>\\n                <tbody class=\\"sale_tbody\\">\\n\\n                    <t t-set=\\"current_section\\" t-value=\\"None\\"/>\\n                    <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                    <t t-set=\\"price_field\\" t-value=\\"'price_total' if (hide_taxes_details or doc.company_price_include == 'tax_included') else 'price_subtotal'\\"/>\\n\\n\\n                    <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n\\n                        <t t-set=\\"is_note\\" t-value=\\"line.display_type == 'line_note'\\"/>\\n                        <t t-set=\\"is_section\\" t-value=\\"line.display_type == 'line_section'\\"/>\\n                        <t t-set=\\"is_subsection\\" t-value=\\"line.display_type == 'line_subsection'\\"/>\\n                        <t t-set=\\"is_combo\\" t-value=\\"line.product_type == 'combo'\\"/>\\n\\n                        <t t-if=\\"is_section\\">\\n                            <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                            <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                            <t t-set=\\"line_padding\\" t-value=\\"0\\"/>\\n                            <t t-set=\\"collapse_prices\\" t-value=\\"line.collapse_prices\\"/>\\n                        </t>\\n                        <t t-elif=\\"is_subsection\\">\\n                            <t t-set=\\"current_subsection\\" t-value=\\"line\\"/>\\n                            <t t-set=\\"line_padding\\" t-value=\\"2\\"/>\\n                            <t t-set=\\"collapse_prices\\" t-value=\\"collapse_prices or line.collapse_prices\\"/>\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            <t t-set=\\"line_padding\\" t-value=\\"3 if current_subsection else (2 if current_section else 0)\\"/>\\n                        </t>\\n\\n                        <t t-if=\\"line.combo_item_id\\">\\n                            <t t-set=\\"line_padding\\" t-value=\\"line_padding + 1\\"/>\\n                        </t>\\n\\n                        <t t-set=\\"padding_class\\" t-value=\\"line_padding and ('px-' + str(line_padding)) or ''\\"/>\\n                        <t t-set=\\"show_section_total\\" t-value=\\"is_section or not line.parent_id.collapse_prices\\"/>\\n\\n                        <t t-if=\\"not line.collapse_composition\\">\\n                            <tr t-if=\\"is_section or is_subsection\\" name=\\"tr_section\\" t-att-class=\\"'fw-bolder o_line_section' if is_section else 'fw-bold o_line_subsection'\\">\\n                                <t t-set=\\"show_section_total\\" t-value=\\"(                                         (                                             is_section                                             or not line.parent_id.collapse_prices                                         )                                         and not line.is_downpayment                                     )\\"/>\\n                                <t t-set=\\"section_name_colspan\\" t-value=\\"colspan_count\\"/>\\n                                <t t-if=\\"not show_section_total\\">\\n                                    <t t-set=\\"section_name_colspan\\" t-value=\\"99\\"/>\\n                                </t>\\n                                <td name=\\"td_section_name\\" t-att-colspan=\\"section_name_colspan\\" t-att-class=\\"padding_class\\">\\n                                    <span t-field=\\"line.name\\">A section title</span>\\n                                </td>\\n                                <td t-if=\\"show_section_total\\" name=\\"td_section_price\\" class=\\"text-end o_price_total\\">\\n                                    <span name=\\"price_subtotal_section\\" t-out=\\"line._get_section_totals(price_field)\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': doc.currency_id}\\">\\n                                        27.00\\n                                    </span>\\n                                </td>\\n                            </tr>\\n                            <tr t-elif=\\"is_note\\" name=\\"tr_note\\" class=\\"fst-italic o_line_note\\">\\n                                <td name=\\"td_note_name\\" colspan=\\"99\\" t-att-class=\\"padding_class\\">\\n                                    <span t-field=\\"line.name\\">A note, whose content usually applies to the section or product above.</span>\\n                                </td>\\n                            </tr>\\n                            <tr t-elif=\\"is_combo\\" name=\\"tr_combo\\" class=\\"fw-bold o_line_subsection\\">\\n                                <td name=\\"td_combo_name\\" t-att-colspan=\\"colspan_count\\" t-att-class=\\"padding_class\\">\\n                                    <span t-field=\\"line.name\\">Combo Product</span>\\n                                    x <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'widget': 'integer'}\\"/>\\n                                </td>\\n                                <td name=\\"td_combo_price\\" class=\\"text-end o_price_total\\">\\n                                    <span t-if=\\"not collapse_prices\\" name=\\"price_subtotal_combo\\" t-out=\\"line._get_combo_totals(price_field)\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': doc.currency_id}\\">\\n                                        27.00\\n                                    </span>\\n                                </td>\\n                            </tr>\\n                            <tr t-else=\\"\\" name=\\"tr_product\\">\\n                                <td name=\\"td_product_name\\" t-att-class=\\"padding_class\\">\\n                                    <span t-field=\\"line.name\\">Bacon Burger</span>\\n                                </td>\\n                                <td name=\\"td_product_quantity\\" class=\\"o_td_quantity text-end\\">\\n                                    <span t-field=\\"line.product_uom_qty\\" class=\\"text-nowrap\\">3</span>\\n                                    <span t-field=\\"line.product_uom_id\\">units</span>\\n                                    <span t-if=\\"line.product_uom_id != line.product_id.uom_id\\" class=\\"text-muted small\\">\\n                                        <t t-set=\\"quantity_in_product_uom\\" t-value=\\"line.product_uom_id._compute_quantity(line.product_uom_qty, line.product_id.uom_id)\\"/>\\n                                        <br/><span t-esc=\\"quantity_in_product_uom\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Unit'}\\"/> <span t-field=\\"line.product_id.uom_id\\"/>\\n                                    </span>\\n                                </td>\\n                                <td name=\\"td_product_priceunit\\" class=\\"text-end text-nowrap\\">\\n                                    <span t-if=\\"not collapse_prices and line.discount &lt; 0\\" t-out=\\"(1 - line.discount / 100.0) * line.price_unit\\" t-options=\\"{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Price&quot;}\\"/>\\n                                    <span t-elif=\\"not collapse_prices\\" t-field=\\"line.price_unit\\">\\n                                        25.00\\n                                    </span>\\n                                </td>\\n                                <td t-if=\\"display_discount\\" name=\\"td_product_discount\\" class=\\"text-end\\">\\n                                    <t t-if=\\"not collapse_prices\\">\\n                                        <!-- ! Always check collapse_prices separately; keep discount condition below for XPath -->\\n                                        <span t-if=\\"line.discount &gt; 0\\" t-field=\\"line.discount\\">-</span>\\n                                    </t>\\n                                </td>\\n                                <t t-set=\\"taxes\\" t-value=\\"', '.join(tax.tax_label for tax in line.tax_ids if tax.tax_label)\\"/>\\n                                <td t-if=\\"display_taxes\\" name=\\"td_product_taxes\\" t-attf-class=\\"text-end {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}\\">\\n                                    <span t-out=\\"taxes\\">Tax 15%</span>\\n                                </td>\\n                                <td name=\\"td_product_subtotal\\" class=\\"text-end o_price_total\\">\\n                                    <t t-if=\\"not line.is_downpayment and not collapse_prices\\">\\n                                        <span t-if=\\"price_field == 'price_subtotal'\\" t-field=\\"line.price_subtotal\\">\\n                                            27.00\\n                                        </span>\\n                                        <span t-else=\\"\\" t-field=\\"line.price_total\\">\\n                                            27.00\\n                                        </span>\\n                                    </t>\\n                                </td>\\n                            </tr>\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            <!-- Displaying the section inner content, grouped by taxes -->\\n                            <tr t-foreach=\\"line._get_grouped_section_summary(display_taxes)\\" t-as=\\"section_line\\" name=\\"tr_section_group\\" class=\\"o_line_section\\">\\n                                <td name=\\"td_section_group_name\\" t-att-class=\\"padding_class\\">\\n                                    <span t-field=\\"line.name\\">\\n                                        Section Summary\\n                                    </span>\\n                                </td>\\n                                <td name=\\"td_section_group_quantity\\" class=\\"text-end text-nowrap\\">\\n                                    <span>1.00 Units</span>\\n                                </td>\\n                                <td name=\\"td_section_group_priceunit\\" class=\\"text-end text-nowrap\\">\\n                                    <span t-if=\\"show_section_total\\" name=\\"price_subtotal_section_grouped\\" t-out=\\"section_line['price_subtotal']\\" t-options=\\"{'widget': 'monetary', 'display_currency': doc.currency_id}\\">\\n                                        25.00\\n                                    </span>\\n                                </td>\\n                                <td t-if=\\"display_discount\\" name=\\"td_section_group_discount\\">\\n                                    <!-- NOTE: not computed atm, but at least provides the API for it if needed in the future -->\\n                                    <t t-set=\\"aggregated_discount\\" t-value=\\"section_line.get('discount', 0)\\"/>\\n                                    <span t-if=\\"aggregated_discount\\" t-out=\\"aggregated_discount\\">-</span>\\n                                </td>\\n                                <td t-if=\\"display_taxes\\" name=\\"td_section_group_taxes\\" t-attf-class=\\"text-end {{ 'text-nowrap' if len(section_line['tax_labels']) &lt; 10 else '' }}\\">\\n                                    <span t-out=\\"', '.join(section_line['tax_labels'])\\">\\n                                        Tax 15%\\n                                    </span>\\n                                </td>\\n                                <td name=\\"td_section_group_total\\" class=\\"text-end o_price_total\\">\\n                                    <span t-if=\\"show_section_total\\" t-out=\\"section_line[price_field]\\" t-options=\\"{'widget': 'monetary', 'display_currency': doc.currency_id}\\">\\n                                        30.00\\n                                    </span>\\n                                </td>\\n                            </tr>\\n                        </t>\\n                    </t>\\n                </tbody>\\n            </table>\\n            <div class=\\"clearfix\\" name=\\"so_total_summary\\">\\n                <div id=\\"total\\" class=\\"row mt-n3\\" name=\\"total\\">\\n                    <div t-attf-class=\\"#{'col-6' if report_type != 'html' else 'col-sm-7 col-md-6'} ms-auto\\">\\n                        <table class=\\"o_total_table table table-borderless\\">\\n                            <!-- Tax totals -->\\n                            <t t-call=\\"sale.document_tax_totals\\">\\n                                <t t-set=\\"tax_totals\\" t-value=\\"doc.tax_totals\\"/>\\n                                <t t-set=\\"currency\\" t-value=\\"doc.currency_id\\"/>\\n                            </t>\\n                        </table>\\n                    </div>\\n                </div>\\n            </div>\\n            <div class=\\"oe_structure\\"/>\\n\\n            <div t-if=\\"not doc.signature or not doc.env.context.get('sale_include_signature')\\" class=\\"oe_structure\\"/>\\n            <div t-else=\\"\\" class=\\"mt-4 ml64 mr4\\" name=\\"signature\\">\\n                <div class=\\"offset-8\\">\\n                    <strong>Signature</strong>\\n                </div>\\n                <div class=\\"offset-8\\">\\n                    <img t-att-src=\\"image_data_uri(doc.signature)\\" style=\\"max-height: 4cm; max-width: 8cm;\\"/>\\n                </div>\\n                <div class=\\"offset-8 text-center\\">\\n                    <span t-field=\\"doc.signed_by\\">Oscar Morgan</span>\\n                </div>\\n            </div>\\n            <div>\\n                <span t-field=\\"doc.note\\" t-attf-style=\\"#{'text-align:justify;text-justify:inter-word;' if doc.company_id.terms_type != 'html' else ''}\\" name=\\"order_note\\"/>\\n                <p t-if=\\"not is_html_empty(doc.payment_term_id.note)\\">\\n                    <span t-field=\\"doc.payment_term_id.note\\">The payment should also be transmitted with love</span>\\n                </p>\\n                <div class=\\"oe_structure\\"/>\\n                <p t-if=\\"doc.fiscal_position_id and not is_html_empty(doc.fiscal_position_id.sudo().note)\\" id=\\"fiscal_position_remark\\">\\n                    <strong>Fiscal Position Remark:</strong>\\n                    <span t-field=\\"doc.fiscal_position_id.sudo().note\\">No further requirements for this payment</span>\\n                </p>\\n            </div>\\n            <div class=\\"oe_structure\\"/>\\n        </div>\\n    </t>\\n</t>", "es_ES": "<t t-name=\\"sale.report_saleorder_document\\">\\n    <t t-call=\\"web.external_layout\\">\\n        <t t-set=\\"doc\\" t-value=\\"doc.with_context(lang=doc.partner_id.lang)\\"/>\\n        <t t-set=\\"forced_vat\\" t-value=\\"doc.fiscal_position_id.foreign_vat\\"/> <!-- So that it appears in the footer of the report instead of the company VAT if it's set -->\\n        <t t-set=\\"address\\">\\n            <div t-field=\\"doc.partner_id\\" class=\\"mb-0\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}\\"/>\\n            <p t-if=\\"doc.partner_id.vat\\" class=\\"mb-0\\">\\n                <t t-if=\\"doc.company_id.account_fiscal_country_id.vat_label\\" t-out=\\"doc.company_id.account_fiscal_country_id.vat_label\\"/>\\n                <t t-else=\\"\\">NIF</t>: <span t-field=\\"doc.partner_id.vat\\"/>\\n            </p>\\n        </t>\\n        <t t-if=\\"doc.partner_shipping_id == doc.partner_invoice_id                              and doc.partner_invoice_id != doc.partner_id                              or doc.partner_shipping_id != doc.partner_invoice_id\\">\\n            <t t-set=\\"information_block\\">\\n                <t t-if=\\"doc.partner_shipping_id == doc.partner_invoice_id\\">\\n                    <strong>\\n                        Invoicing and Shipping Address\\n                    </strong>\\n                    <div t-field=\\"doc.partner_invoice_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                </t>\\n                <div t-else=\\"\\" class=\\"row\\">\\n                    <div t-if=\\"doc.partner_id != doc.partner_invoice_id\\" t-att-class=\\"doc.partner_id != doc.partner_shipping_id and 'col-6 pe-1'\\">\\n                        <strong>\\n                            Dirección de facturación\\n                        </strong>\\n                        <div t-field=\\"doc.partner_invoice_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                    </div>\\n                    <div t-if=\\"doc.partner_id != doc.partner_shipping_id\\" t-att-class=\\"doc.partner_id != doc.partner_invoice_id and 'col-6 ps-1'\\">\\n                        <strong>\\n                            Shipping Address\\n                        </strong>\\n                        <div t-field=\\"doc.partner_shipping_id\\" t-options=\\"{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}\\"/>\\n                    </div>\\n                </div>\\n            </t>\\n        </t>\\n        <div class=\\"page\\">\\n            <div class=\\"oe_structure\\"/>\\n\\n            <t t-set=\\"is_proforma\\" t-value=\\"env.context.get('proforma', False) or is_pro_forma\\"/>\\n            <t t-set=\\"layout_document_title\\">\\n                <span t-if=\\"is_proforma\\">Número de factura proforma </span>\\n                <span t-elif=\\"doc.state in ['draft','sent']\\">Presupuesto # </span>\\n                <span t-else=\\"\\">Pedido nº </span>\\n                <span t-field=\\"doc.name\\">SO0000</span>\\n            </t>\\n\\n            <div class=\\"row mb-4\\" id=\\"informations\\">\\n                <div t-if=\\"doc.client_order_ref\\" class=\\"col\\" name=\\"informations_reference\\">\\n                    <strong>Su referencia</strong>\\n                    <div t-field=\\"doc.client_order_ref\\">SO0000</div>\\n                </div>\\n                <div t-if=\\"doc.date_order\\" class=\\"col\\" name=\\"informations_date\\">\\n                    <strong t-if=\\"is_proforma\\">Fecha de emisión</strong>\\n                    <strong t-elif=\\"doc.state in ['draft', 'sent']\\">Fecha del presupuesto</strong>\\n                    <strong t-else=\\"\\">Fecha del pedido</strong>\\n                    <div t-field=\\"doc.date_order\\" t-options=\\"{&quot;widget&quot;: &quot;date&quot;}\\">2023-12-31</div>\\n                </div>\\n                <div t-if=\\"doc.validity_date and doc.state in ['draft', 'sent']\\" class=\\"col\\" name=\\"expiration_date\\">\\n                    <strong>Vencimiento</strong>\\n                    <div t-field=\\"doc.validity_date\\">2023-12-31</div>\\n                </div>\\n                <div t-if=\\"doc.commitment_date\\" class=\\"col\\" name=\\"delivery_date\\">\\n                    <strong>Fecha de entrega</strong>\\n                    <div t-field=\\"doc.commitment_date\\" t-options=\\"{'widget': 'date'}\\">\\n                        2023-12-31\\n                    </div>\\n                </div>\\n                <div t-if=\\"doc.user_id.name\\" class=\\"col\\">\\n                    <strong>Comercial</strong>\\n                    <div t-field=\\"doc.user_id\\">Mitchell Admin</div>\\n                </div>\\n            </div>\\n\\n            <!-- Is there a discount on at least one line? -->\\n            <t t-set=\\"lines_to_report\\" t-value=\\"doc._get_order_lines_to_report()\\"/>\\n            <t t-set=\\"display_discount\\" t-value=\\"any(l.discount &gt; 0 for l in lines_to_report)\\"/>\\n            <!-- Hide taxes AND show taxed amounts on lines -->\\n            <t t-set=\\"hide_taxes_details\\" t-value=\\"False\\"/>\\n            <t t-set=\\"display_taxes\\" t-value=\\"not hide_taxes_details and any(l._has_taxes() for l in lines_to_report)\\"/>\\n\\n            <div class=\\"oe_structure\\"/>\\n            <table class=\\"o_has_total_table table o_main_table table-borderless\\">\\n                <!-- In case we want to repeat the header, remove \\"display: table-row-group\\" -->\\n                <thead style=\\"display: table-row-group\\">\\n                    <!-- Initialize the dynamic column counter -->\\n                    <t t-set=\\"colspan_count\\" t-value=\\"0\\"/>\\n                    <tr>\\n                        <th name=\\"th_description\\" class=\\"text-start\\">\\n                            <t t-set=\\"colspan_count\\" t-value=\\"colspan_count + 1\\"/>\\n                            Descripción\\n                        </th>\\n                        <th name=\\"th_quantity\\" class=\\"text-end text-nowrap\\">\\n                            <t t-set=\\"colspan_count\\" t-value=\\"colspan_count + 1\\"/>\\n                            Cantidad\\n                        </th>\\n                        <th name=\\"th_priceunit\\" class=\\"text-end text-nowrap\\">\\n                            <t t-set=\\"colspan_count\\" t-value=\\"colspan_count + 1\\"/>\\n                            Precio unitario\\n                        </th>\\n                        <th name=\\"th_discount\\" t-if=\\"display_discount\\" class=\\"text-end\\">\\n                            <t t-set=\\"colspan_count\\" t-value=\\"colspan_count + 1\\"/>\\n                            <span>Desc.%</span>\\n                        </th>\\n                        <th name=\\"th_taxes\\" t-if=\\"display_taxes\\" class=\\"text-end\\">\\n                            <t t-set=\\"colspan_count\\" t-value=\\"colspan_count + 1\\"/>\\n                            <span>Impuestos</span>\\n                        </th>\\n                        <th name=\\"th_subtotal\\" class=\\"text-end\\">\\n                            <span>Importe</span>\\n                        </th>\\n                    </tr>\\n                </thead>\\n                <tbody class=\\"sale_tbody\\">\\n\\n                    <t t-set=\\"current_section\\" t-value=\\"None\\"/>\\n                    <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                    <t t-set=\\"price_field\\" t-value=\\"'price_total' if (hide_taxes_details or doc.company_price_include == 'tax_included') else 'price_subtotal'\\"/>\\n\\n\\n                    <t t-foreach=\\"lines_to_report\\" t-as=\\"line\\">\\n\\n                        <t t-set=\\"is_note\\" t-value=\\"line.display_type == 'line_note'\\"/>\\n                        <t t-set=\\"is_section\\" t-value=\\"line.display_type == 'line_section'\\"/>\\n                        <t t-set=\\"is_subsection\\" t-value=\\"line.display_type == 'line_subsection'\\"/>\\n                        <t t-set=\\"is_combo\\" t-value=\\"line.product_type == 'combo'\\"/>\\n\\n                        <t t-if=\\"is_section\\">\\n                            <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                            <t t-set=\\"current_subsection\\" t-value=\\"None\\"/>\\n                            <t t-set=\\"line_padding\\" t-value=\\"0\\"/>\\n                            <t t-set=\\"collapse_prices\\" t-value=\\"line.collapse_prices\\"/>\\n                        </t>\\n                        <t t-elif=\\"is_subsection\\">\\n                            <t t-set=\\"current_subsection\\" t-value=\\"line\\"/>\\n                            <t t-set=\\"line_padding\\" t-value=\\"2\\"/>\\n                            <t t-set=\\"collapse_prices\\" t-value=\\"collapse_prices or line.collapse_prices\\"/>\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            <t t-set=\\"line_padding\\" t-value=\\"3 if current_subsection else (2 if current_section else 0)\\"/>\\n                        </t>\\n\\n                        <t t-if=\\"line.combo_item_id\\">\\n                            <t t-set=\\"line_padding\\" t-value=\\"line_padding + 1\\"/>\\n                        </t>\\n\\n                        <t t-set=\\"padding_class\\" t-value=\\"line_padding and ('px-' + str(line_padding)) or ''\\"/>\\n                        <t t-set=\\"show_section_total\\" t-value=\\"is_section or not line.parent_id.collapse_prices\\"/>\\n\\n                        <t t-if=\\"not line.collapse_composition\\">\\n                            <tr t-if=\\"is_section or is_subsection\\" name=\\"tr_section\\" t-att-class=\\"'fw-bolder o_line_section' if is_section else 'fw-bold o_line_subsection'\\">\\n                                <t t-set=\\"show_section_total\\" t-value=\\"(                                         (                                             is_section                                             or not line.parent_id.collapse_prices                                         )                                         and not line.is_downpayment                                     )\\"/>\\n                                <t t-set=\\"section_name_colspan\\" t-value=\\"colspan_count\\"/>\\n                                <t t-if=\\"not show_section_total\\">\\n                                    <t t-set=\\"section_name_colspan\\" t-value=\\"99\\"/>\\n                                </t>\\n                                <td name=\\"td_section_name\\" t-att-colspan=\\"section_name_colspan\\" t-att-class=\\"padding_class\\">\\n                                    <span t-field=\\"line.name\\">Un título de sección</span>\\n                                </td>\\n                                <td t-if=\\"show_section_total\\" name=\\"td_section_price\\" class=\\"text-end o_price_total\\">\\n                                    <span name=\\"price_subtotal_section\\" t-out=\\"line._get_section_totals(price_field)\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': doc.currency_id}\\">\\n                                        27.00\\n                                    </span>\\n                                </td>\\n                            </tr>\\n                            <tr t-elif=\\"is_note\\" name=\\"tr_note\\" class=\\"fst-italic o_line_note\\">\\n                                <td name=\\"td_note_name\\" colspan=\\"99\\" t-att-class=\\"padding_class\\">\\n                                    <span t-field=\\"line.name\\">Una nota, cuyo contenido generalmente aplica a la sección o el producto anterior.</span>\\n                                </td>\\n                            </tr>\\n                            <tr t-elif=\\"is_combo\\" name=\\"tr_combo\\" class=\\"fw-bold o_line_subsection\\">\\n                                <td name=\\"td_combo_name\\" t-att-colspan=\\"colspan_count\\" t-att-class=\\"padding_class\\">\\n                                    <span t-field=\\"line.name\\">Producto combinado</span>\\n                                    x <span t-field=\\"line.product_uom_qty\\" t-options=\\"{'widget': 'integer'}\\"/>\\n                                </td>\\n                                <td name=\\"td_combo_price\\" class=\\"text-end o_price_total\\">\\n                                    <span t-if=\\"not collapse_prices\\" name=\\"price_subtotal_combo\\" t-out=\\"line._get_combo_totals(price_field)\\" class=\\"text-nowrap\\" t-options=\\"{'widget': 'monetary', 'display_currency': doc.currency_id}\\">\\n                                        27.00\\n                                    </span>\\n                                </td>\\n                            </tr>\\n                            <tr t-else=\\"\\" name=\\"tr_product\\">\\n                                <td name=\\"td_product_name\\" t-att-class=\\"padding_class\\">\\n                                    <span t-field=\\"line.name\\">Hamburguesa con bacon</span>\\n                                </td>\\n                                <td name=\\"td_product_quantity\\" class=\\"o_td_quantity text-end\\">\\n                                    <span t-field=\\"line.product_uom_qty\\" class=\\"text-nowrap\\">3</span>\\n                                    <span t-field=\\"line.product_uom_id\\">unidades</span>\\n                                    <span t-if=\\"line.product_uom_id != line.product_id.uom_id\\" class=\\"text-muted small\\">\\n                                        <t t-set=\\"quantity_in_product_uom\\" t-value=\\"line.product_uom_id._compute_quantity(line.product_uom_qty, line.product_id.uom_id)\\"/>\\n                                        <br/><span t-esc=\\"quantity_in_product_uom\\" t-options=\\"{'widget': 'float', 'decimal_precision': 'Product Unit'}\\"/> <span t-field=\\"line.product_id.uom_id\\"/>\\n                                    </span>\\n                                </td>\\n                                <td name=\\"td_product_priceunit\\" class=\\"text-end text-nowrap\\">\\n                                    <span t-if=\\"not collapse_prices and line.discount &lt; 0\\" t-out=\\"(1 - line.discount / 100.0) * line.price_unit\\" t-options=\\"{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Price&quot;}\\"/>\\n                                    <span t-elif=\\"not collapse_prices\\" t-field=\\"line.price_unit\\">\\n                                        25.00\\n                                    </span>\\n                                </td>\\n                                <td t-if=\\"display_discount\\" name=\\"td_product_discount\\" class=\\"text-end\\">\\n                                    <t t-if=\\"not collapse_prices\\">\\n                                        <!-- ! Always check collapse_prices separately; keep discount condition below for XPath -->\\n                                        <span t-if=\\"line.discount &gt; 0\\" t-field=\\"line.discount\\">-</span>\\n                                    </t>\\n                                </td>\\n                                <t t-set=\\"taxes\\" t-value=\\"', '.join(tax.tax_label for tax in line.tax_ids if tax.tax_label)\\"/>\\n                                <td t-if=\\"display_taxes\\" name=\\"td_product_taxes\\" t-attf-class=\\"text-end {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}\\">\\n                                    <span t-out=\\"taxes\\">Impuesto del 15 %</span>\\n                                </td>\\n                                <td name=\\"td_product_subtotal\\" class=\\"text-end o_price_total\\">\\n                                    <t t-if=\\"not line.is_downpayment and not collapse_prices\\">\\n                                        <span t-if=\\"price_field == 'price_subtotal'\\" t-field=\\"line.price_subtotal\\">\\n                                            27.00\\n                                        </span>\\n                                        <span t-else=\\"\\" t-field=\\"line.price_total\\">\\n                                            27.00\\n                                        </span>\\n                                    </t>\\n                                </td>\\n                            </tr>\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            <!-- Displaying the section inner content, grouped by taxes -->\\n                            <tr t-foreach=\\"line._get_grouped_section_summary(display_taxes)\\" t-as=\\"section_line\\" name=\\"tr_section_group\\" class=\\"o_line_section\\">\\n                                <td name=\\"td_section_group_name\\" t-att-class=\\"padding_class\\">\\n                                    <span t-field=\\"line.name\\">\\n                                        Resumen de la sección\\n                                    </span>\\n                                </td>\\n                                <td name=\\"td_section_group_quantity\\" class=\\"text-end text-nowrap\\">\\n                                    <span>1,00 unidades</span>\\n                                </td>\\n                                <td name=\\"td_section_group_priceunit\\" class=\\"text-end text-nowrap\\">\\n                                    <span t-if=\\"show_section_total\\" name=\\"price_subtotal_section_grouped\\" t-out=\\"section_line['price_subtotal']\\" t-options=\\"{'widget': 'monetary', 'display_currency': doc.currency_id}\\">\\n                                        25.00\\n                                    </span>\\n                                </td>\\n                                <td t-if=\\"display_discount\\" name=\\"td_section_group_discount\\">\\n                                    <!-- NOTE: not computed atm, but at least provides the API for it if needed in the future -->\\n                                    <t t-set=\\"aggregated_discount\\" t-value=\\"section_line.get('discount', 0)\\"/>\\n                                    <span t-if=\\"aggregated_discount\\" t-out=\\"aggregated_discount\\">-</span>\\n                                </td>\\n                                <td t-if=\\"display_taxes\\" name=\\"td_section_group_taxes\\" t-attf-class=\\"text-end {{ 'text-nowrap' if len(section_line['tax_labels']) &lt; 10 else '' }}\\">\\n                                    <span t-out=\\"', '.join(section_line['tax_labels'])\\">\\n                                        Impuesto del 15 %\\n                                    </span>\\n                                </td>\\n                                <td name=\\"td_section_group_total\\" class=\\"text-end o_price_total\\">\\n                                    <span t-if=\\"show_section_total\\" t-out=\\"section_line[price_field]\\" t-options=\\"{'widget': 'monetary', 'display_currency': doc.currency_id}\\">\\n                                        30.00\\n                                    </span>\\n                                </td>\\n                            </tr>\\n                        </t>\\n                    </t>\\n                </tbody>\\n            </table>\\n            <div class=\\"clearfix\\" name=\\"so_total_summary\\">\\n                <div id=\\"total\\" class=\\"row mt-n3\\" name=\\"total\\">\\n                    <div t-attf-class=\\"#{'col-6' if report_type != 'html' else 'col-sm-7 col-md-6'} ms-auto\\">\\n                        <table class=\\"o_total_table table table-borderless\\">\\n                            <!-- Tax totals -->\\n                            <t t-call=\\"sale.document_tax_totals\\">\\n                                <t t-set=\\"tax_totals\\" t-value=\\"doc.tax_totals\\"/>\\n                                <t t-set=\\"currency\\" t-value=\\"doc.currency_id\\"/>\\n                            </t>\\n                        </table>\\n                    </div>\\n                </div>\\n            </div>\\n            <div class=\\"oe_structure\\"/>\\n\\n            <div t-if=\\"not doc.signature or not doc.env.context.get('sale_include_signature')\\" class=\\"oe_structure\\"/>\\n            <div t-else=\\"\\" class=\\"mt-4 ml64 mr4\\" name=\\"signature\\">\\n                <div class=\\"offset-8\\">\\n                    <strong>Firma</strong>\\n                </div>\\n                <div class=\\"offset-8\\">\\n                    <img t-att-src=\\"image_data_uri(doc.signature)\\" style=\\"max-height: 4cm; max-width: 8cm;\\"/>\\n                </div>\\n                <div class=\\"offset-8 text-center\\">\\n                    <span t-field=\\"doc.signed_by\\">Oscar Morgan</span>\\n                </div>\\n            </div>\\n            <div>\\n                <span t-field=\\"doc.note\\" t-attf-style=\\"#{'text-align:justify;text-justify:inter-word;' if doc.company_id.terms_type != 'html' else ''}\\" name=\\"order_note\\"/>\\n                <p t-if=\\"not is_html_empty(doc.payment_term_id.note)\\">\\n                    <span t-field=\\"doc.payment_term_id.note\\">El pago también debe transmitirse con amor</span>\\n                </p>\\n                <div class=\\"oe_structure\\"/>\\n                <p t-if=\\"doc.fiscal_position_id and not is_html_empty(doc.fiscal_position_id.sudo().note)\\" id=\\"fiscal_position_remark\\">\\n                    <strong>Comentario sobre la posición fiscal:</strong>\\n                    <span t-field=\\"doc.fiscal_position_id.sudo().note\\">No hay otro requisito para este pago</span>\\n                </p>\\n            </div>\\n            <div class=\\"oe_structure\\"/>\\n        </div>\\n    </t>\\n</t>"}	<?xml version="1.0"?>\n<t t-name="sale.report_saleorder_document">\n    <t t-call="web.external_layout">\n        <t t-set="doc" t-value="doc.with_context(lang=doc.partner_id.lang)"/>\n        <t t-set="forced_vat" t-value="doc.fiscal_position_id.foreign_vat"/> <!-- So that it appears in the footer of the report instead of the company VAT if it's set -->\n        <t t-set="address">\n            <div t-field="doc.partner_id" class="mb-0" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;], &quot;no_marker&quot;: True}"/>\n            <p t-if="doc.partner_id.vat" class="mb-0">\n                <t t-if="doc.company_id.account_fiscal_country_id.vat_label" t-out="doc.company_id.account_fiscal_country_id.vat_label"/>\n                <t t-else="">Tax ID</t>: <span t-field="doc.partner_id.vat"/>\n            </p>\n        </t>\n        <t t-if="doc.partner_shipping_id == doc.partner_invoice_id                              and doc.partner_invoice_id != doc.partner_id                              or doc.partner_shipping_id != doc.partner_invoice_id">\n            <t t-set="information_block">\n                <t t-if="doc.partner_shipping_id == doc.partner_invoice_id">\n                    <strong>\n                        Invoicing and Shipping Address\n                    </strong>\n                    <div t-field="doc.partner_invoice_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                </t>\n                <div t-else="" class="row">\n                    <div t-if="doc.partner_id != doc.partner_invoice_id" t-att-class="doc.partner_id != doc.partner_shipping_id and 'col-6 pe-1'">\n                        <strong>\n                            Invoicing Address\n                        </strong>\n                        <div t-field="doc.partner_invoice_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                    </div>\n                    <div t-if="doc.partner_id != doc.partner_shipping_id" t-att-class="doc.partner_id != doc.partner_invoice_id and 'col-6 ps-1'">\n                        <strong>\n                            Shipping Address\n                        </strong>\n                        <div t-field="doc.partner_shipping_id" t-options="{&quot;widget&quot;: &quot;contact&quot;, &quot;fields&quot;: [&quot;address&quot;, &quot;name&quot;, &quot;phone&quot;], &quot;no_marker&quot;: True, &quot;phone_icons&quot;: True}"/>\n                    </div>\n                </div>\n            </t>\n        </t>\n        <div class="page">\n            <div class="oe_structure"/>\n\n            <t t-set="is_proforma" t-value="env.context.get('proforma', False) or is_pro_forma"/>\n            <t t-set="layout_document_title">\n                <span t-if="is_proforma">Pro-Forma Invoice # </span>\n                <span t-elif="doc.state in ['draft','sent']">Quotation # </span>\n                <span t-else="">Order # </span>\n                <span t-field="doc.name">SO0000</span>\n            </t>\n\n            <div class="row mb-4" id="informations">\n                <div t-if="doc.client_order_ref" class="col" name="informations_reference">\n                    <strong>Your Reference</strong>\n                    <div t-field="doc.client_order_ref">SO0000</div>\n                </div>\n                <div t-if="doc.date_order" class="col" name="informations_date">\n                    <strong t-if="is_proforma">Issued Date</strong>\n                    <strong t-elif="doc.state in ['draft', 'sent']">Quotation Date</strong>\n                    <strong t-else="">Order Date</strong>\n                    <div t-field="doc.date_order" t-options="{&quot;widget&quot;: &quot;date&quot;}">2023-12-31</div>\n                </div>\n                <div t-if="doc.validity_date and doc.state in ['draft', 'sent']" class="col" name="expiration_date">\n                    <strong>Expiration</strong>\n                    <div t-field="doc.validity_date">2023-12-31</div>\n                </div>\n                <div t-if="doc.commitment_date" class="col" name="delivery_date">\n                    <strong>Delivery Date</strong>\n                    <div t-field="doc.commitment_date" t-options="{'widget': 'date'}">\n                        2023-12-31\n                    </div>\n                </div>\n                <div t-if="doc.user_id.name" class="col">\n                    <strong>Salesperson</strong>\n                    <div t-field="doc.user_id">Mitchell Admin</div>\n                </div>\n            </div>\n\n            <!-- Is there a discount on at least one line? -->\n            <t t-set="lines_to_report" t-value="doc._get_order_lines_to_report()"/>\n            <t t-set="display_discount" t-value="any(l.discount &gt; 0 for l in lines_to_report)"/>\n            <!-- Hide taxes AND show taxed amounts on lines -->\n            <t t-set="hide_taxes_details" t-value="False"/>\n            <t t-set="display_taxes" t-value="not hide_taxes_details and any(l._has_taxes() for l in lines_to_report)"/>\n\n            <div class="oe_structure"/>\n            <table class="o_has_total_table table o_main_table table-borderless">\n                <!-- In case we want to repeat the header, remove "display: table-row-group" -->\n                <thead style="display: table-row-group">\n                    <!-- Initialize the dynamic column counter -->\n                    <t t-set="colspan_count" t-value="0"/>\n                    <tr>\n                        <th name="th_description" class="text-start">\n                            <t t-set="colspan_count" t-value="colspan_count + 1"/>\n                            Description\n                        </th>\n                        <th name="th_quantity" class="text-end text-nowrap">\n                            <t t-set="colspan_count" t-value="colspan_count + 1"/>\n                            Quantity\n                        </th>\n                        <th name="th_priceunit" class="text-end text-nowrap">\n                            <t t-set="colspan_count" t-value="colspan_count + 1"/>\n                            Unit Price\n                        </th>\n                        <th name="th_discount" t-if="display_discount" class="text-end">\n                            <t t-set="colspan_count" t-value="colspan_count + 1"/>\n                            <span>Disc.%</span>\n                        </th>\n                        <th name="th_taxes" t-if="display_taxes" class="text-end">\n                            <t t-set="colspan_count" t-value="colspan_count + 1"/>\n                            <span>Taxes</span>\n                        </th>\n                        <th name="th_subtotal" class="text-end">\n                            <span>Amount</span>\n                        </th>\n                    </tr>\n                </thead>\n                <tbody class="sale_tbody">\n\n                    <t t-set="current_section" t-value="None"/>\n                    <t t-set="current_subsection" t-value="None"/>\n                    <t t-set="price_field" t-value="'price_total' if (hide_taxes_details or doc.company_price_include == 'tax_included') else 'price_subtotal'"/>\n\n\n                    <t t-foreach="lines_to_report" t-as="line">\n\n                        <t t-set="is_note" t-value="line.display_type == 'line_note'"/>\n                        <t t-set="is_section" t-value="line.display_type == 'line_section'"/>\n                        <t t-set="is_subsection" t-value="line.display_type == 'line_subsection'"/>\n                        <t t-set="is_combo" t-value="line.product_type == 'combo'"/>\n\n                        <t t-if="is_section">\n                            <t t-set="current_section" t-value="line"/>\n                            <t t-set="current_subsection" t-value="None"/>\n                            <t t-set="line_padding" t-value="0"/>\n                            <t t-set="collapse_prices" t-value="line.collapse_prices"/>\n                        </t>\n                        <t t-elif="is_subsection">\n                            <t t-set="current_subsection" t-value="line"/>\n                            <t t-set="line_padding" t-value="2"/>\n                            <t t-set="collapse_prices" t-value="collapse_prices or line.collapse_prices"/>\n                        </t>\n                        <t t-else="">\n                            <t t-set="line_padding" t-value="3 if current_subsection else (2 if current_section else 0)"/>\n                        </t>\n\n                        <t t-if="line.combo_item_id">\n                            <t t-set="line_padding" t-value="line_padding + 1"/>\n                        </t>\n\n                        <t t-set="padding_class" t-value="line_padding and ('px-' + str(line_padding)) or ''"/>\n                        <t t-set="show_section_total" t-value="is_section or not line.parent_id.collapse_prices"/>\n\n                        <t t-if="not line.collapse_composition">\n                            <tr t-if="is_section or is_subsection" name="tr_section" t-att-class="'fw-bolder o_line_section' if is_section else 'fw-bold o_line_subsection'">\n                                <t t-set="show_section_total" t-value="(                                         (                                             is_section                                             or not line.parent_id.collapse_prices                                         )                                         and not line.is_downpayment                                     )"/>\n                                <t t-set="section_name_colspan" t-value="colspan_count"/>\n                                <t t-if="not show_section_total">\n                                    <t t-set="section_name_colspan" t-value="99"/>\n                                </t>\n                                <td name="td_section_name" t-att-colspan="section_name_colspan" t-att-class="padding_class">\n                                    <span t-field="line.name">A section title</span>\n                                </td>\n                                <td t-if="show_section_total" name="td_section_price" class="text-end o_price_total">\n                                    <span name="price_subtotal_section" t-out="line._get_section_totals(price_field)" class="text-nowrap" t-options="{'widget': 'monetary', 'display_currency': doc.currency_id}">\n                                        27.00\n                                    </span>\n                                </td>\n                            </tr>\n                            <tr t-elif="is_note" name="tr_note" class="fst-italic o_line_note">\n                                <td name="td_note_name" colspan="99" t-att-class="padding_class">\n                                    <span t-field="line.name">A note, whose content usually applies to the section or product above.</span>\n                                </td>\n                            </tr>\n                            <tr t-elif="is_combo" name="tr_combo" class="fw-bold o_line_subsection">\n                                <td name="td_combo_name" t-att-colspan="colspan_count" t-att-class="padding_class">\n                                    <span t-field="line.name">Combo Product</span>\n                                    x <span t-field="line.product_uom_qty" t-options="{'widget': 'integer'}"/>\n                                </td>\n                                <td name="td_combo_price" class="text-end o_price_total">\n                                    <span t-if="not collapse_prices" name="price_subtotal_combo" t-out="line._get_combo_totals(price_field)" class="text-nowrap" t-options="{'widget': 'monetary', 'display_currency': doc.currency_id}">\n                                        27.00\n                                    </span>\n                                </td>\n                            </tr>\n                            <tr t-else="" name="tr_product">\n                                <td name="td_product_name" t-att-class="padding_class">\n                                    <span t-field="line.name">Bacon Burger</span>\n                                </td>\n                                <td name="td_product_quantity" class="o_td_quantity text-end">\n                                    <span t-field="line.product_uom_qty" class="text-nowrap">3</span>\n                                    <span t-field="line.product_uom_id">units</span>\n                                    <span t-if="line.product_uom_id != line.product_id.uom_id" class="text-muted small">\n                                        <t t-set="quantity_in_product_uom" t-value="line.product_uom_id._compute_quantity(line.product_uom_qty, line.product_id.uom_id)"/>\n                                        <br/><span t-esc="quantity_in_product_uom" t-options="{'widget': 'float', 'decimal_precision': 'Product Unit'}"/> <span t-field="line.product_id.uom_id"/>\n                                    </span>\n                                </td>\n                                <td name="td_product_priceunit" class="text-end text-nowrap">\n                                    <span t-if="not collapse_prices and line.discount &lt; 0" t-out="(1 - line.discount / 100.0) * line.price_unit" t-options="{&quot;widget&quot;: &quot;float&quot;, &quot;decimal_precision&quot;: &quot;Product Price&quot;}"/>\n                                    <span t-elif="not collapse_prices" t-field="line.price_unit">\n                                        25.00\n                                    </span>\n                                </td>\n                                <td t-if="display_discount" name="td_product_discount" class="text-end">\n                                    <t t-if="not collapse_prices">\n                                        <!-- ! Always check collapse_prices separately; keep discount condition below for XPath -->\n                                        <span t-if="line.discount &gt; 0" t-field="line.discount">-</span>\n                                    </t>\n                                </td>\n                                <t t-set="taxes" t-value="', '.join(tax.tax_label for tax in line.tax_ids if tax.tax_label)"/>\n                                <td t-if="display_taxes" name="td_product_taxes" t-attf-class="text-end {{ 'text-nowrap' if len(taxes) &lt; 10 else '' }}">\n                                    <span t-out="taxes">Tax 15%</span>\n                                </td>\n                                <td name="td_product_subtotal" class="text-end o_price_total">\n                                    <t t-if="not line.is_downpayment and not collapse_prices">\n                                        <span t-if="price_field == 'price_subtotal'" t-field="line.price_subtotal">\n                                            27.00\n                                        </span>\n                                        <span t-else="" t-field="line.price_total">\n                                            27.00\n                                        </span>\n                                    </t>\n                                </td>\n                            </tr>\n                        </t>\n                        <t t-else="">\n                            <!-- Displaying the section inner content, grouped by taxes -->\n                            <tr t-foreach="line._get_grouped_section_summary(display_taxes)" t-as="section_line" name="tr_section_group" class="o_line_section">\n                                <td name="td_section_group_name" t-att-class="padding_class">\n                                    <span t-field="line.name">\n                                        Section Summary\n                                    </span>\n                                </td>\n                                <td name="td_section_group_quantity" class="text-end text-nowrap">\n                                    <span>1.00 Units</span>\n                                </td>\n                                <td name="td_section_group_priceunit" class="text-end text-nowrap">\n                                    <span t-if="show_section_total" name="price_subtotal_section_grouped" t-out="section_line['price_subtotal']" t-options="{'widget': 'monetary', 'display_currency': doc.currency_id}">\n                                        25.00\n                                    </span>\n                                </td>\n                                <td t-if="display_discount" name="td_section_group_discount">\n                                    <!-- NOTE: not computed atm, but at least provides the API for it if needed in the future -->\n                                    <t t-set="aggregated_discount" t-value="section_line.get('discount', 0)"/>\n                                    <span t-if="aggregated_discount" t-out="aggregated_discount">-</span>\n                                </td>\n                                <td t-if="display_taxes" name="td_section_group_taxes" t-attf-class="text-end {{ 'text-nowrap' if len(section_line['tax_labels']) &lt; 10 else '' }}">\n                                    <span t-out="', '.join(section_line['tax_labels'])">\n                                        Tax 15%\n                                    </span>\n                                </td>\n                                <td name="td_section_group_total" class="text-end o_price_total">\n                                    <span t-if="show_section_total" t-out="section_line[price_field]" t-options="{'widget': 'monetary', 'display_currency': doc.currency_id}">\n                                        30.00\n                                    </span>\n                                </td>\n                            </tr>\n                        </t>\n                    </t>\n                </tbody>\n            </table>\n            <div class="clearfix" name="so_total_summary">\n                <div id="total" class="row mt-n3" name="total">\n                    <div t-attf-class="#{'col-6' if report_type != 'html' else 'col-sm-7 col-md-6'} ms-auto">\n                        <table class="o_total_table table table-borderless">\n                            <!-- Tax totals -->\n                            <t t-call="sale.document_tax_totals">\n                                <t t-set="tax_totals" t-value="doc.tax_totals"/>\n                                <t t-set="currency" t-value="doc.currency_id"/>\n                            </t>\n                        </table>\n                    </div>\n                </div>\n            </div>\n            <div class="oe_structure"/>\n\n            <div t-if="not doc.signature or not doc.env.context.get('sale_include_signature')" class="oe_structure"/>\n            <div t-else="" class="mt-4 ml64 mr4" name="signature">\n                <div class="offset-8">\n                    <strong>Signature</strong>\n                </div>\n                <div class="offset-8">\n                    <img t-att-src="image_data_uri(doc.signature)" style="max-height: 4cm; max-width: 8cm;"/>\n                </div>\n                <div class="offset-8 text-center">\n                    <span t-field="doc.signed_by">Oscar Morgan</span>\n                </div>\n            </div>\n            <div>\n                <span t-field="doc.note" t-attf-style="#{'text-align:justify;text-justify:inter-word;' if doc.company_id.terms_type != 'html' else ''}" name="order_note"/>\n                <p t-if="not is_html_empty(doc.payment_term_id.note)">\n                    <span t-field="doc.payment_term_id.note">The payment should also be transmitted with love</span>\n                </p>\n                <div class="oe_structure"/>\n                <p t-if="doc.fiscal_position_id and not is_html_empty(doc.fiscal_position_id.sudo().note)" id="fiscal_position_remark">\n                    <strong>Fiscal Position Remark:</strong>\n                    <span t-field="doc.fiscal_position_id.sudo().note">No further requirements for this payment</span>\n                </p>\n            </div>\n            <div class="oe_structure"/>\n        </div>\n    </t>\n</t>\n\n	f	t	2026-11-17 08:08:45.50362	2026-11-17 08:08:45.50362	f
