" type="action" name="sale.act_res_partner_2_sale_order" groups="sales_team.group_sale_salesman" icon="fa-usd">\n                    <field string="Sales" name="sale_order_count" widget="statinfo"/>\n                </button>\n            </div>\n            <group name="warnings" position="inside">\n                <group groups="sale.group_warning_sale" col="2">\n                    <separator string="Warning on Sales Orders and Invoices" colspan="2"/>\n                    <field name="sale_warn_msg" placeholder="e.g. This customer has reported recurring issues with previous orders." nolabel="1" colspan="2"/>\n                </group>\n            </group>\n        </data>	f	t	2026-11-17 08:08:45.50362	2026-11-17 08:08:45.50362	f
