ing.scheduled_date" t-options="{'date_only': True}"/>\n                            </div>\n                        </div>\n                    </t>\n                </div>\n            </div>\n            <t t-set="returns" t-value="delivery_orders.return_ids.sorted('create_date', reverse=True)"/>\n            <div t-if="returns" class="col-12 col-lg-6 mb-4">\n                <h4 class="mb-1">Returns</h4>\n                <hr class="mt-1 mb-2"/>\n                <t t-foreach="returns" t-as="picking">\n                    <t t-set="delivery_report_url" t-value="'/my/picking/pdf/%s?%s' % (picking.id, keep_query())"/>\n                    <div name="return">\n                        <div name="return_details" class="d-flex justify-content-between align-items-center">\n                            <a t-att-href="delivery_report_url">\n                                <span t-esc="picking.name"/>\n                            </a>\n                            <span t-if="picking.state == 'done'" class="small badge rounded-pill text-bg-success orders_label_text_align">\n                                <i class="fa fa-fw fa-truck"/> Received\n                            </span>\n                            <span t-elif="picking.state == 'cancel'" class="small badge rounded-pill text-bg-danger orders_label_text_align">\n                                <i class="fa fa-fw fa-times"/> Cancelled\n                            </span>\n                            <span t-elif="picking.state in ['draft', 'waiting', 'confirmed', 'assigned']" class="small badge rounded-pill text-bg-info orders_label_text_align">\n                                <i class="fa fa-fw fa-clock-o"/> Awaiting arrival\n                            </span>\n                        </div>\n                        <div class="small d-lg-inline-block">\n                            Date:\n                            <span class="text-muted" t-field="picking.date_done" t-options="{'date_only': True}"/>\n              