ion: none !important; font-weight: 400; background-color: {{ object.email_secondary_color or '#875A7B' }}; border-radius:3px\\">\\n                                            Send invoices\\n                                        </a>\\n                                    </div>\\n                                </td>\\n                                <td valign=\\"middle\\" align=\\"right\\">\\n                                    <t t-if=\\"not object.uses_default_logo\\">\\n                                        <img t-att-src=\\"'/logo.png?company=%s' % object.id\\" style=\\"height: auto; width: 80px; margin-right: 10px;\\" t-att-alt=\\"'%s' % object.name\\"/>\\n                                    </t>\\n                                </td>\\n                            </tr>\\n                            <tr>\\n                                <td colspan=\\"2\\" style=\\"text-align:center;\\">\\n                                    <hr style=\\"background-color:#CCCCCC; border:none; height:1px; margin:16px 0;\\"/>\\n                                </td>\\n                            </tr>\\n                        </table>\\n                    </td>\\n                </tr>\\n                <!-- BODY -->\\n                <tr>\\n                    <td align=\\"center\\">\\n                        <table width=\\"590\\" cellpadding=\\"0\\" cellspacing=\\"0\\" style=\\"padding: 0px 8px; background-color: white; border-collapse:separate;\\">\\n                            <tr>\\n                                <td style=\\"font-size: 14px;\\">\\n                                    <p>Dear <t t-out=\\"object.name or ''\\">YourCompany</t>,</p>\\n\\n                                    <p>We have successfully added your company to the <strong>Peppol Network</strong>.</p>\\n\\n                                    <p>You can now <strong>send<t t-if=\\"object.account_peppol_proxy_state == 'receiver'\\"> and receive</t></strong> electronic invoices via Odoo — completely free of charge.</p>\\n\\n                                    <p>Best regards,</p>\\n\\n                                    <p style=\\"margin-bottom: 24px;\\">The Odoo Team</p>\\n                                </td>\\n                            </tr>\\n                        </table>\\n                    </td>\\n                </tr>\\n            </table>\\n        </td>\\n    </tr>\\n</table>\\n            ", "es_ES": "<table border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" style=\\"padding-top: 16px; background-color: #F1F1F1; font-family:Verdana, Arial,sans-serif; color: #454748; width: 100%; border-collapse:separate;\\">\\n    <tr>\\n        <td align=\\"center\\">\\n            <table border=\\"0\\" cellpadding=\\"0\\" cellspacing=\\"0\\" width=\\"590\\" style=\\"padding: 16px; background-color: white; color: #454748; border-collapse:separate;\\">\\n                <!-- ENCABEZADO -->\\n                <tr>\\n                    <td align=\\"center\\" style=\\"min-width: 590px;\\">\\n                        <table width=\\"590\\" cellpadding=\\"0\\" cellspacing=\\"0\\" style=\\"padding: 0px 8px; background-color: white; border-collapse:separate;\\">\\n                            <tr>\\n                                <td valign=\\"middle\\">\\n                                    <span style=\\"font-size: 10px;\\">Notificación</span>\\n                                    <br/>\\n                                    <span style=\\"font-size: 20px; font-weight: bold;\\">\\n                                        Bienvenido a Peppol\\n                                    </span>\\n                                    <div style=\\"margin-bottom: 5px; margin-top: 18px;\\">\\n                                        <a t-attf-href=\\"/odoo/accounting/\\" target=\\"_blank\\" t-attf-style=\\"padding: 8px 12px; font-size: 12px; color: {{ object.email_primary_color or '#FFFFFF' }}; text-decoration: none !important; font-weight: 400; background-color: {{ object.email_secondary_color or '#875A7B' }}; border-radius:3px\\">\\n                                            Enviar facturas\\n                                        </a>\\n                                    </div>\\n                                </td>\\n                                <td valign=\\"middle\\" align=\\"right\\">\\n                                    <t t-if=\\"not object.uses_default_logo\\">\\n                                        <img t-att-src=\\"'/logo.png?company=%s' % object.id\\" style=\\"height: auto; width: 80px; margin-right: 10px;\\" t-att-alt=\\"'%s' % object.name\\"/>\\n                                    </t>\\n                                </td>\\n                            </tr>\\n                            <tr>\\n                                <td colspan=\\"2\\" style=\\"text-align:center;\\">\\n                                    <hr style=\\"background-color:#CCCCCC; border:none; height:1px; margin:16px 0;\\"/>\\n                                </td>\\n                            </tr>\\n                        </table>\\n                    </td>\\n                </tr>\\n                <!-- CUERPO -->\\n                <tr>\\n                    <td align=\\"center\\">\\n                        <table width=\\"590\\" cellpadding=\\"0\\" cellspacing=\\"0\\" style=\\"padding: 0px 8px; background-color: white; border-collapse:separate;\\">\\n                            <tr>\\n                                <td style=\\"font-size: 14px;\\">\\n                                    <p>Estimado/a <t t-out=\\"object.name or ''\\">SuCompañía</t>:</p>\\n\\n                                    <p>Hemos añadido su empresa a la <strong>red Peppol</strong> con éxito.</p>\\n\\n                                    <p>Ahora puede <strong>enviar<t t-if=\\"object.account_peppol_proxy_state == 'receiver'\\"> y recibir</t></strong> facturas electrónicas a través de Odoo sin coste adicional.</p>\\n\\n                                    <p>Saludos,</p>\\n\\n                                    <p style=\\"margin-bottom: 24px;\\">El equipo de Odoo</p>\\n                                </td>\\n                            </tr>\\n                        </table>\\n                    </td>\\n                </tr>\\n            </table>\\n        </td>\\n    </tr>\\n</table>\\n            "}	t	f	t	2026-11-17 08:08:35.240899	2026-11-17 08:08:35.240899
18	545	\N	\N	\N	1	1	sale/data/mail_template_data.xml	\N	sale.order	{{ (object.user_id.email_formatted or object.company_id.email_formatted or user.email_formatted) }}	\N	\N	\N	\N	\N	\N	{"en_US": "Sales: Order Confirmation", "es_ES": "Ventas: confirmación de pedido"}	{"en_US": "Sent to customers on order confirmation", "es_ES": "Enviado a los clientes al confirmar un pedido"}	{"en_US": "{{ object.company_id.name }} {{ (object.get_portal_last_transaction().state == 'pending') and 'Pending Order' or 'Order' }} (Ref {{ object.name or 'n/a' }})", "es_ES": "{{ object.company_id.name }} {{ (object.get_portal_last_transaction().state == 'pending') and 'Pedido pendiente' or 'Pedido' }} (Ref {{ object.name or 'no aplica' }})"}	{"en_US": "<div style=\\"margin: 0px; padding: 0px;\\">\\n    <p style=\\"margin: 0px; padding: 0px; font-size: 12px;\\">\\n        Hello,\\n        <br/><br/>\\n        <t t-set=\\"tx_sudo\\" t-value=\\"object.get_portal_last_transaction()\\"/>\\n        Your order <span style=\\"font-weight:bold;\\" t-out=\\"object.name or ''\\">S00049</span> amounting in <span style=\\"font-weight:bold;\\" t-out=\\"format_amount(object.amount_total, object.currency_id) or ''\\">$ 10.00</span>\\n        <t t-if=\\"object.state == 'sale' or (tx_sudo and tx_sudo.state in ('done', 'authorized'))\\">\\n            has been confirmed.<br/>\\n            Thank you for your trust!\\n        </t>\\n        <t t-elif=\\"tx_sudo and tx_sudo.state == 'pending'\\">\\n            is pending. It will be confirmed when the payment is received.\\n            <t t-if=\\"object.reference\\">\\n                Your payment reference is <span style=\\"font-weight:bold;\\" t-out=\\"object.reference or ''\\"/>.\\n            </t>\\n        </t>\\n        <br/>\\n        <t t-set=\\"documents\\" t-value=\\"object._get_product_documents()\\"/>\\n        <t t-if=\\"documents\\">\\n            <br/>\\n            <t t-if=\\"len(documents)&gt;1\\">\\n                Here are some additional documents that may interest you:\\n            </t>\\n            <t t-else=\\"\\">\\n                Here is an additional document that may interest you:\\n            </t>\\n            <ul style=\\"margin-bottom: 0;\\">\\n                <t t-foreach=\\"documents\\" t-as=\\"document\\">\\n                    <li style=\\"font-size: 13px;\\">\\n                        <a t-out=\\"document.ir_attachment_id.name\\" t-att-href=\\"object.get_portal_url('/document/' + str(document.id))\\" t-att-target=\\"target\\"/>\\n                    </li>\\n                </t>\\n            </ul>\\n        </t>\\n        <br/>\\n        Do not hesitate to contact us if you have any questions.\\n        <t t-if=\\"not is_html_empty(object.user_id.signature)\\" data-o-mail-quote-container=\\"1\\">\\n            <div data-o-mail-quote=\\"1\\">--<br data-o-mail-quote=\\"1\\"/><t t-out=\\"object.user_id.signature or ''\\" data-o-mail-quote=\\"1\\">Mitchell Admin</t></div>\\n        </t>\\n    </p>\\n<t t-if=\\"hasattr(object, 'website_id') and object.website_id\\">\\n    <div style=\\"margin: 0px; padding: 0px;\\">\\n        <table width=\\"100%\\" style=\\"color: #454748; font-size: 12px; border-collapse: collapse; white-space: nowrap;\\">\\n            <tr style=\\"border-bottom: 2px solid #dee2e6;\\">\\n                <td style=\\"width: 150px;\\"><span style=\\"font-weight:bold;\\">Products</span></td>\\n                <td/>\\n                <td width=\\"15%\\" align=\\"center\\"><span style=\\"font-weight:bold;\\">Quantity</span></td>\\n                <td width=\\"20%\\" align=\\"right\\">\\n                    <span style=\\"font-weight:bold;\\">\\n                        <t t-if=\\"hasattr(object, 'website_id') and object.website_id.show_line_subtotals_tax_selection == 'tax_excluded'\\">\\n                            Tax Excl.\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            Tax Incl.\\n                        </t>\\n                    </span>\\n                </td>\\n            </tr>\\n        </table>\\n        <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n        <t t-foreach=\\"object.order_line\\" t-as=\\"line\\">\\n            <t t-set=\\"line_subtotal\\" t-value=\\"                     line.price_subtotal                     if hasattr(object, 'website_id') and object.website_id.show_line_subtotals_tax_selection == 'tax_excluded'                     else line.price_total                 \\"/>\\n            <t t-set=\\"current_subtotal\\" t-value=\\"current_subtotal + line_subtotal\\"/>\\n            <t t-if=\\"(not hasattr(line, 'is_delivery') or not line.is_delivery) and (                     line.display_type in ['line_section', 'line_subsection', 'line_note']                     or line.product_type == 'combo'                 )\\">\\n                <table width=\\"100%\\" style=\\"color: #454748; font-size: 12px; border-collapse: collapse;\\">\\n                    <t t-set=\\"loop_cycle_number\\" t-value=\\"loop_cycle_number or 0\\"/>\\n                    <tr t-att-style=\\"'background-color: #f2f2f2' if loop_cycle_number % 2 == 0 else 'background-color: #ffffff'\\">\\n                        <t t-set=\\"loop_cycle_number\\" t-value=\\"loop_cycle_number + 1\\"/>\\n                        <td colspan=\\"4\\">\\n                            <t t-if=\\"line.display_type in ('line_section', 'line_subsection') or line.product_type == 'combo'\\">\\n                                <span t-att-style=\\"'font-weight:bold;' if line.display_type == 'line_subsection' else 'font-weight:bolder;'\\" t-out=\\"line.name or ''\\">Taking care of Trees Course</span>\\n                                <t t-set=\\"current_section\\" t-value=\\"line\\"/>\\n                                <t t-set=\\"current_subtotal\\" t-value=\\"0\\"/>\\n                            </t>\\n                            <t t-elif=\\"line.display_type == 'line_note'\\">\\n                                <i t-out=\\"line.name or ''\\">Taking care of Trees Course</i>\\n                            </t>\\n                        </td>\\n                    </tr>\\n                </table>\\n            </t>\\n            <t t-elif=\\"(not hasattr(line, 'is_delivery') or not line.is_delivery)\\">\\n                <table width=\\"100%\\" style=\\"color: #454748; font-size: 12px; border-collapse: collapse;\\">\\n                    <t t-set=\\"loop_cycle_number\\" t-value=\\"loop_cycle_number or 0\\"/>\\n                    <tr t-att-style=\\"'background-color: #f2f2f2' if loop_cycle_number % 2 == 0 else 'background-color: #ffffff'\\">\\n                        <t t-set=\\"loop_cycle_number\\" t-value=\\"loop_cycle_number + 1\\"/>\\n                        <td style=\\"width: 150px;\\">\\n                            <img t-attf-src=\\"/web/image/product.product/{{ line.product_id.id }}/image_128\\" t-attf-style=\\"width: 64px; height: {{hasattr(object, 'website_id') and object.website_id and object.website_id._get_product_image_ratio_height() or '64px'}}; object-fit: cover; object-position: center;\\" alt=\\"Product image\\"/>\\n                        </td>\\n                        <td align=\\"left\\" t-out=\\"line.product_id.name or ''\\">\\tTaking care of Trees Course</td>\\n                        <td width=\\"15%\\" align=\\"center\\" t-out=\\"line.product_uom_qty or ''\\">1</td>\\n                        <td width=\\"20%\\" align=\\"right\\"><span style=\\"font-weight:bold; white-space: nowrap;\\">\\n                        <t t-if=\\"hasattr(object, 'website_id') and object.website_id.show_line_subtotals_tax_selection == 'tax_excluded'\\">\\n                            <t t-out=\\"format_amount(line.price_reduce_taxexcl, object.currency_id) or ''\\">$ 10.00</t>\\n                        </t>\\n                        <t t-else=\\"\\">\\n                            <t t-out=\\"format_amount(line.price_reduce_taxinc, object.currency_id) or ''\\">$ 10.00</t>\\n     